window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[177]={"id":"177","numero":177,"titre":"Médicaments anti-infectieux","objectifs":[{"id":"177-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un antibiotique","contenu":"<p>Un <span class=\"kw-def\">antibiotique</span> est une substance — d'origine <strong>naturelle</strong> (produite par des champignons ou des bactéries pour se défendre) ou <strong>synthétique</strong> — capable d'<strong>inhiber la croissance</strong> <span class=\"kw-etio\">bactérienne</span> (effet <span class=\"kw-def\">bactériostatique</span>) ou de <strong>détruire</strong> la bactérie (effet <span class=\"kw-def\">bactéricide</span>).</p>\n      <p>Un antibiotique n'agit que sur <span class=\"kw-clinique\">les</span> <strong>bactéries</strong> : il est <span class=\"kw-ci\">inactif sur les virus, les champignons et les parasites</span>. La majorité des classes sont issues de champignons ; deux familles font exception, entièrement <strong>synthétiques</strong> : les <span class=\"kw-ttt\">quinolones</span> et les <span class=\"kw-ttt\">sulfamides</span>.</p>\n      <p>De moins en moins de nouveaux antibiotiques sont découverts alors que <span class=\"kw-clinique\">les</span> résistances progressent : leur <strong>utilisation rationnelle</strong> est devenue indispensable.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":0},{"id":"177-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition du spectre antibactérien","contenu":"<p>Le <span class=\"kw-def\">spectre antibactérien</span> d'un antibiotique est l'<strong>ensemble des espèces bactériennes sur lesquelles il est actif</strong>.</p>\n      <p>On distingue le spectre <strong>étroit</strong> (peu d'espèces ciblées) du spectre <strong>large</strong> ; et le spectre <em>théorique</em> du <span class=\"kw-def\">spectre utile</span> — <span class=\"kw-clinique\">les</span> bactéries pour lesquelles l'antibiotique a un intérêt clinique réel. Le spectre est borné par les <span class=\"kw-def\">résistances naturelles</span> (présentes chez toutes les souches d'une espèce) et amputé par les <span class=\"kw-def\">résistances acquises</span>.</p>\n      <p>Il s'évalue <em>in vitro</em> par la <span class=\"kw-bio\">concentration minimale inhibitrice</span> (<span class=\"kw-bio\">CMI</span>) : la concentration la plus basse permettant d'inhiber la croissance <span class=\"kw-etio\">bactérienne</span> aux posologies usuelles. L'<span class=\"kw-bio\">antibiogramme</span> mesure le niveau de sensibilité d'une souche donnée face aux antibiotiques.</p>","frequence":0},{"id":"177-3","rang":"A","rubrique":"Définition","titre":"Connaître les différentes classes d’antibiotiques","contenu":"<p><span class=\"kw-clinique\">Les</span> antibiotiques se classent selon leur <strong>cible <span class=\"kw-etio\">bactérienne</span></strong> :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Cible</th><th>Classes d'antibiotiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Paroi <span class=\"kw-etio\">bactérienne</span></strong></td><td><span class=\"kw-ttt\">β-lactamines</span> (pénicillines, céphalosporines, monobactames, carbapénèmes) ; <span class=\"kw-ttt\">glycopeptides</span> ; <span class=\"kw-ttt\">fosfomycine</span></td></tr>\n          <tr><td><strong>Synthèse protéique</strong> (ribosome)</td><td><span class=\"kw-ttt\">aminosides</span> et <span class=\"kw-ttt\">cyclines</span> (sous-unité 30S) ; <span class=\"kw-ttt\">macrolides</span>, <span class=\"kw-ttt\">lincosamides</span>, <span class=\"kw-ttt\">oxazolidinones</span> (sous-unité 50S)</td></tr>\n          <tr><td><strong>Acides nucléiques</strong></td><td><span class=\"kw-ttt\">fluoroquinolones</span> (ADN gyrase) ; <span class=\"kw-ttt\">imidazolés</span> ; <span class=\"kw-ttt\">rifampicine</span> (ARN)</td></tr>\n          <tr><td><strong>Synthèse des folates</strong></td><td><span class=\"kw-ttt\">sulfamides</span> — dont le <span class=\"kw-ttt\">cotrimoxazole</span></td></tr>\n          <tr><td><strong>Membrane <span class=\"kw-etio\">bactérienne</span></strong></td><td><span class=\"kw-ttt\">daptomycine</span> ; <span class=\"kw-ttt\">colistine</span> / polymyxines</td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-ttt\">rifampicine</span> est aussi un antituberculeux majeur, toujours utilisé en <strong>association</strong> (jamais en monothérapie).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":0},{"id":"177-4","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les principes du mode d’action d’un antibiotique","contenu":"<p><span class=\"kw-clinique\">Les</span> antibiotiques interfèrent avec le <span class=\"kw-def\">cycle réplicatif</span> des bactéries : ils sont donc surtout actifs sur les bactéries <strong>en phase de multiplication</strong>. Les bactéries en croissance lente — <span class=\"kw-alerte\">infection sur matériel</span>, <span class=\"kw-etio\">endocardite</span> — y sont moins sensibles.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Classe</th><th>Mécanisme d'action</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">β-lactamines</span></td><td>Liaison aux <span class=\"kw-def\">PLP</span> (protéines de liaison des pénicillines) : blocage de la synthèse du peptidoglycane de la paroi</td></tr>\n          <tr><td><span class=\"kw-ttt\">Glycopeptides</span></td><td>Blocage de la formation du peptidoglycane : inhibition de la synthèse de la paroi</td></tr>\n          <tr><td><span class=\"kw-ttt\">Aminosides</span>, <span class=\"kw-ttt\">macrolides</span>, <span class=\"kw-ttt\">lincosamides</span>, <span class=\"kw-ttt\">cyclines</span></td><td>Inhibition de la synthèse protéique (fixation sur le ribosome, 30S ou 50S)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Fluoroquinolones</span></td><td>Inhibition de l'ADN gyrase / topoisomérase : blocage de l'élongation de l'ADN</td></tr>\n          <tr><td><span class=\"kw-ttt\">Imidazolés</span>, <span class=\"kw-ttt\">rifampicine</span></td><td>Lésions de l'ADN <span class=\"kw-etio\">bactérien</span> / inhibition de la synthèse de l'ARN</td></tr>\n          <tr><td><span class=\"kw-ttt\">Sulfamides</span></td><td>Inhibition de la synthèse des folates</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout\">\n        <strong>Quatre conséquences à connaître :</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">β-lactamines</span> sont <span class=\"kw-ci\">inactives sur les mycoplasmes</span> (dépourvus de paroi).</li>\n          <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">glycopeptides</span> sont <span class=\"kw-ci\">inactifs sur les BGN</span> : leur membrane externe ne laisse pas passer ces grosses molécules.</li>\n          <li><strong>Synergie</strong> <span class=\"kw-ttt\">β-lactamine</span> + <span class=\"kw-ttt\">aminoside</span> sur <span class=\"kw-etio\">streptocoque</span> et <span class=\"kw-etio\">entérocoque</span> : la β-lactamine détruit la paroi, l'aminoside accède alors à sa cible ribosomale.</li>\n          <li>Seuls <span class=\"kw-clinique\">les</span> antibiotiques pénétrant dans la cellule sont actifs sur les <span class=\"kw-def\">bactéries intracellulaires</span> : <span class=\"kw-ttt\">macrolides</span>, <span class=\"kw-ttt\">fluoroquinolones</span>, <span class=\"kw-ttt\">rifampicine</span>, <span class=\"kw-ttt\">cyclines</span>.</li>\n        </ul>\n      </div>","frequence":2},{"id":"177-5","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux pénicillines","contenu":"<p><span class=\"kw-clinique\">Les</span> pénicillines sont des <span class=\"kw-ttt\">β-lactamines</span> : liaison aux <span class=\"kw-def\">PLP</span>, <strong>bactéricides temps-dépendants</strong>. Élimination urinaire. Quatre sous-familles à distinguer :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th></th><th>Péni G / V</th><th>Péni A &amp; <span class=\"kw-ttt\">Augmentin</span></th><th>Péni M</th><th>Carboxy / Uréido</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Molécules</strong></td>\n            <td><span class=\"kw-ttt\">Péni V</span> (oracilline, PO) ; <span class=\"kw-ttt\">Péni G</span> (IV) ; forme retard <span class=\"kw-ttt\">benzathine benzylpénicilline</span> (IM)</td>\n            <td><span class=\"kw-ttt\">Amoxicilline</span> ; <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> (<span class=\"kw-ttt\">Augmentin</span>)</td>\n            <td><span class=\"kw-ttt\">Oxacilline</span>, <span class=\"kw-ttt\">cloxacilline</span></td>\n            <td><span class=\"kw-ttt\">Pipéracilline</span> (± tazobactam) ; <span class=\"kw-ttt\">ticarcilline</span> ; <span class=\"kw-ttt\">pivmécillinam</span></td>\n          </tr>\n          <tr>\n            <td><strong>Spectre utile</strong></td>\n            <td><span class=\"kw-etio\">Streptocoques</span> ; <em>Corynebacterium diphteriae</em> ; <em><span class=\"kw-etio\">Fusobacterium</span></em> ; <span class=\"kw-etio\">tréponème</span> (<span class=\"kw-clinique\">syphilis</span>)</td>\n            <td>Spectre Péni G + <span class=\"kw-etio\">pneumocoque</span> péni-S, <em>E. faecalis</em>, <span class=\"kw-etio\">Listeria</span>, <span class=\"kw-etio\">méningocoque</span>, <em>Borrelia</em>, entérobactéries gpe 1.<br><span class=\"kw-ttt\">Augmentin</span> : + bactéries productrices de pénicillinase (SASM, <em><span class=\"kw-etio\">Haemophilus</span></em>, <span class=\"kw-etio\">anaérobies</span>)</td>\n            <td><span class=\"kw-etio\">Staphylocoque méti-S</span> (doré et autres)</td>\n            <td>Spectre <span class=\"kw-ttt\">amoxicilline</span> étendu aux BGN, dont <span class=\"kw-etio\">Pseudomonas aeruginosa</span></td>\n          </tr>\n          <tr>\n            <td><strong>Résistances</strong></td>\n            <td>Naturelle : BGN.<br><span class=\"kw-etio\">Acquise</span> : <span class=\"kw-alerte\">pneumocoque (PSDP)</span>, <span class=\"kw-etio\">staphylocoque</span></td>\n            <td>Naturelle : entérobactéries gpe 2-3, <span class=\"kw-etio\">Pseudomonas</span>.<br><span class=\"kw-etio\">Acquise</span> : <span class=\"kw-alerte\">staphylocoque (95 %)</span>, <span class=\"kw-alerte\">E. coli (40 %)</span>, PSDP</td>\n            <td>Naturelle : BGN.<br><span class=\"kw-etio\">Acquise</span> : <span class=\"kw-etio\">SARM</span></td>\n            <td><span class=\"kw-alerte\">EBLSE</span> ; <span class=\"kw-bio\">SARM</span> ; intracellulaires</td>\n          </tr>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td>Péni V : prophylaxie pneumococcique du splénectomisé.<br>Péni G IV : neurosyphilis.<br>Péni retard IM : <span class=\"kw-clinique\">syphilis</span> ; prophylaxie de l'<span class=\"kw-clinique\">érysipèle</span> récidivant</td>\n            <td>Angine à SGA, OMA, sinusite, <span class=\"kw-etio\">pneumonie</span> à <span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-etio\">listériose</span>, <span class=\"kw-etio\">méningite</span> à méningo/pneumo sensible, EI à strepto/<span class=\"kw-etio\">entérocoque</span> + prophylaxie de l'EI, Lyme primaire.<br><span class=\"kw-ttt\">Augmentin</span> : DHBNN après morsure, infection stomato</td>\n            <td>Infections systémiques à SASM : <strong><span class=\"kw-clinique\">bactériémie</span>, <span class=\"kw-etio\">endocardite</span>, infection ostéo-articulaire</strong> (voie IV stricte — biodisponibilité orale médiocre)</td>\n            <td>Infections nosocomiales ; IU à <span class=\"kw-bio\">EBLSE</span> ; <span class=\"kw-clinique\">péritonite</span> avec <span class=\"kw-etio\">sepsis</span> ; PNP à <span class=\"kw-etio\">Pseudomonas</span> ; neutropénie fébrile</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Effets indésirables</strong> communs : <span class=\"kw-clinique\">réactions allergiques</span>, troubles digestifs ; rare <span class=\"kw-alerte\">encéphalopathie aux β-lactamines</span>. <strong><span class=\"kw-ci\">Grossesse</span></strong> : autorisées à tous <span class=\"kw-clinique\">les</span> trimestres.</p>\n      <div class=\"obj-callout\">\n        <strong><span class=\"kw-ci\">Allergie</span> aux β-lactamines — piège classique.</strong> Le risque est largement <span class=\"kw-alerte\">surestimé</span> : <span class=\"kw-chiffre\">80-90 %</span> des patients se disant allergiques ne le sont pas, et <span class=\"kw-clinique\">les</span> allergies croisées entre familles de β-lactamines sont rares (<span class=\"kw-chiffre\">1-5 %</span>). À l'interrogatoire : préciser le délai, la nature des manifestations, l'<span class=\"kw-clinique\">évolution</span> à l'arrêt.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-etio\">Endocardite</span> infectieuse · 151 — <span class=\"kw-etio\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span></em></p>","frequence":2},{"id":"177-6","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux céphalosporines de deuxième génération","contenu":"<p>Molécule de référence : <span class=\"kw-ttt\">céfuroxime</span> (la <span class=\"kw-ttt\">céfoxitine</span> est rattachée à la 2ᵉ génération). Ce sont des <span class=\"kw-ttt\">β-lactamines</span> bactéricides temps-dépendantes.</p>\n      <ul>\n        <li><strong>Spectre :</strong> cocci Gram positif (<span class=\"kw-etio\">streptocoques</span>, SAMS) et entérobactéries des groupes 0-1.</li>\n        <li><strong>Indications :</strong> <span class=\"kw-ttt\">antibioprophylaxie chirurgicale</span> (formes injectables IV) ; infections ORL bénignes en cas d'<span class=\"kw-ci\">allergie à l'amoxicilline</span>.</li>\n        <li><strong>Effets indésirables :</strong> <span class=\"kw-clinique\">réactions allergiques</span> (<span class=\"kw-ci\">allergie</span> croisée avec la pénicilline dans &lt; <span class=\"kw-chiffre\">5 %</span> des cas).</li>\n      </ul>\n      <p>Place globalement <strong>limitée</strong> dans l'arsenal antibiotique courant.</p>","frequence":0},{"id":"177-7","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux céphalosporines de troisième génération orales","contenu":"<p>Molécules : <span class=\"kw-ttt\">cefpodoxime</span> et <span class=\"kw-ttt\">céfixime</span>. Ce sont des <span class=\"kw-ttt\">β-lactamines</span> bactéricides temps-dépendantes.</p>\n      <ul>\n        <li><strong>Spectre :</strong> cocci Gram positif (<span class=\"kw-etio\">streptocoques</span>) ; entérobactéries des groupes 1-2.</li>\n        <li><strong>Indications :</strong> <span class=\"kw-ttt\">céfixime</span> → <span class=\"kw-etio\">pyélonéphrite</span> aiguë en <strong>relai d'une forme injectable</strong>. <span class=\"kw-ttt\">Cefpodoxime</span> → sinusite <span class=\"kw-etio\">bactérienne</span> aiguë de l'adulte, angine à SGA, OMA de l'enfant (<strong>2ᵉ intention</strong>).</li>\n        <li><strong>Effets indésirables :</strong> <span class=\"kw-clinique\">allergies</span>, troubles digestifs, acouphènes, <span class=\"kw-clinique\">céphalées</span>, cytolyse.</li>\n      </ul>\n      <div class=\"obj-callout\">\n        <strong>Place limitée.</strong> Mauvaise <span class=\"kw-bio\">biodisponibilité</span> (&lt; <span class=\"kw-chiffre\">50 %</span>, absorption saturable) et <span class=\"kw-alerte\">impact écologique important</span> : <span class=\"kw-clinique\">les</span> C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span> orales ne sont pas un relai des infections urinaires masculines.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-etio\">Infection urinaire</span></em></p>","frequence":0},{"id":"177-8","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux céphalosporines de troisième génération injectables","contenu":"<p><span class=\"kw-ttt\">β-lactamines</span> bactéricides temps-dépendantes, à <strong>bonne <span class=\"kw-def\">diffusion</span> méningée</strong> (à forte dose). Voie IV ou IM (SC possible chez le sujet âgé pour la <span class=\"kw-ttt\">ceftriaxone</span>).</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Sous-groupe</th><th>Molécules</th><th>Spectre</th></tr></thead>\n        <tbody>\n          <tr><td><strong>C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span></strong></td><td><span class=\"kw-ttt\">Ceftriaxone</span> (T½ longue, 1 injection/24 h), <span class=\"kw-ttt\">céfotaxime</span></td><td><span class=\"kw-etio\">Streptocoques</span> (dont pneumocoque), <em>Neisseria</em>, entérobactéries, <em><span class=\"kw-etio\">Haemophilus</span></em></td></tr>\n          <tr><td><strong>C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span>G</span></strong></td><td><span class=\"kw-ttt\">Céfépime</span>, <span class=\"kw-ttt\">ceftazidime</span></td><td>+ <span class=\"kw-etio\">Pseudomonas aeruginosa</span> et entérobactéries à résistance <span class=\"kw-etio\">acquise</span> aux céphalosporinases</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Résistances naturelles :</strong> <span class=\"kw-etio\">Listeria</span> et <span class=\"kw-etio\">entérocoques</span> (PLP de faible affinité) ; bactéries intracellulaires. <strong>Résistance <span class=\"kw-etio\">acquise</span> :</strong> <span class=\"kw-etio\">SARM</span>, <span class=\"kw-alerte\">EBLSE</span>.</p>\n      <p><strong>Indications :</strong> <span class=\"kw-etio\">méningite</span> purulente (traitement <strong>probabiliste</strong>), <span class=\"kw-alerte\">purpura fulminans</span> (<span class=\"kw-ttt\">ceftriaxone</span>), formes graves à BGN (PNA, <span class=\"kw-etio\">prostatite</span>), <span class=\"kw-etio\">pneumocoque</span> de sensibilité diminuée extra-pulmonaire, <span class=\"kw-clinique\">fièvre</span> du <span class=\"kw-clinique\">neutropénique</span>, Lyme aux phases secondaire et tertiaire (ceftriaxone), <span class=\"kw-clinique\">fièvre</span> typhoïde, infection à <span class=\"kw-clinique\">gonocoque</span> (ceftriaxone IM dose unique).</p>\n      <p><strong>Effets indésirables :</strong> <span class=\"kw-clinique\">allergies</span>, leuco-neutropénie, hyperéosinophilie, cytolyse.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-etio\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span> · 152 — <span class=\"kw-etio\">Endocardite</span> infectieuse</em></p>","frequence":1},{"id":"177-9","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux aminosides","contenu":"<p>Molécules : <span class=\"kw-ttt\">gentamicine</span> (plutôt sur <span class=\"kw-clinique\">les</span> Gram positif) et <span class=\"kw-ttt\">amikacine</span> (plutôt sur les Gram négatif). Inhibition de la synthèse protéique par fixation sur la sous-unité <strong>30S</strong>. Bactéricides <strong>concentration-dépendants</strong>.</p>\n      <ul>\n        <li><strong>Voie :</strong> <span class=\"kw-ttt\">IV stricte</span> — aucune absorption entérale.</li>\n        <li><strong>Règle d'or :</strong> <span class=\"kw-alerte\">toujours en association</span> (sauf rares exceptions), sur une durée la plus courte possible — <span class=\"kw-chiffre\">1 à 3 jours</span>.</li>\n        <li><strong>Spectre :</strong> SASM, tous <span class=\"kw-clinique\">les</span> BGN (dont <span class=\"kw-etio\">Pseudomonas</span>), <span class=\"kw-etio\">Listeria</span> ; sur <span class=\"kw-etio\">streptocoque</span>/<span class=\"kw-etio\">entérocoque</span>, sensibilité <strong>restaurée par la synergie</strong> avec une β-lactamine. <span class=\"kw-ci\">Inactifs sur les anaérobies et les intracellulaires</span>.</li>\n        <li><strong><span class=\"kw-def\">Suivi</span> :</strong> dosage du <span class=\"kw-bio\">pic</span> à <span class=\"kw-chiffre\">30 min</span> de l'injection (efficacité) et de la <span class=\"kw-bio\">résiduelle</span> avant l'injection suivante (toxicité).</li>\n      </ul>\n      <div class=\"obj-callout\">\n        <strong>Effets indésirables &amp; <span class=\"kw-ci\">contre-indications</span>.</strong> Toxicité <span class=\"kw-alerte\">cochléo-vestibulaire irréversible</span> ; néphrotoxicité (toxicité tubulaire, le plus souvent réversible). <span class=\"kw-ci\">Myasthénie = contre-indication absolue</span>. <span class=\"kw-ci\">Déconseillés pendant toute la grossesse</span>.\n      </div>\n      <p><strong>Indications :</strong> infections graves à BGN aérobies ou à <span class=\"kw-etio\">Pseudomonas</span>, <span class=\"kw-etio\">endocardite</span> à <span class=\"kw-etio\">streptocoque</span>/<span class=\"kw-etio\">entérocoque</span>, certaines méningites à <span class=\"kw-etio\">Listeria</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-etio\">Endocardite</span> infectieuse</em></p>","frequence":1},{"id":"177-10","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux fluoroquinolones systémiques","contenu":"<p>FQ simples : <span class=\"kw-ttt\">ofloxacine</span>, <span class=\"kw-ttt\">ciprofloxacine</span>. FQ à activité anti-pneumococcique : <span class=\"kw-ttt\">lévofloxacine</span>, <span class=\"kw-ttt\">moxifloxacine</span>. Inhibition de l'<strong>ADN gyrase / topoisomérase</strong>, bactéricides <strong>concentration-dépendants</strong>.</p>\n      <ul>\n        <li><strong>Pharmacocinétique :</strong> très bonne <span class=\"kw-bio\">biodisponibilité orale</span> ; <strong>excellente <span class=\"kw-def\">diffusion</span></strong> dans la prostate, l'os et <span class=\"kw-clinique\">les</span> méninges.</li>\n        <li><strong>Spectre :</strong> bactéries <span class=\"kw-def\">intracellulaires</span>, entérobactéries, SAMS ; <span class=\"kw-etio\">Pseudomonas</span> (<span class=\"kw-ttt\">ciprofloxacine</span>) ; <span class=\"kw-etio\">pneumocoque</span> (<span class=\"kw-ttt\">lévofloxacine</span>, moxifloxacine).</li>\n        <li><strong>Résistances :</strong> naturelles → <span class=\"kw-etio\">entérocoque</span>, <span class=\"kw-etio\">Listeria</span>, <span class=\"kw-etio\">anaérobies</span> ; acquises → <span class=\"kw-bio\">SARM</span>, <span class=\"kw-etio\">Pseudomonas</span>.</li>\n      </ul>\n      <div class=\"obj-callout\">\n        <strong>Effets indésirables marquants.</strong> <span class=\"kw-alerte\">Tendinopathies</span> avec risque de <span class=\"kw-alerte\">rupture tendineuse</span> ; <span class=\"kw-alerte\">allongement du QTc</span> ; troubles neuropsychiques (<span class=\"kw-clinique\">convulsions</span>, <span class=\"kw-clinique\">confusion</span> du sujet âgé) ; <span class=\"kw-clinique\">phototoxicité</span> ; hépatites. <strong><span class=\"kw-ci\">Contre-indications</span> :</strong> <span class=\"kw-ci\">enfant</span> (risque de fusion des cartilages de croissance), <span class=\"kw-ci\">grossesse</span>, ATCD de tendinopathie sous quinolone.\n      </div>\n      <p><strong><span class=\"kw-ci\">Précautions d'emploi</span> :</strong> à utiliser <strong>après documentation</strong>, jamais en probabiliste — <span class=\"kw-alerte\">sauf PNA et infection urinaire masculine</span>. Éviter <span class=\"kw-clinique\">les</span> prescriptions répétées (fort impact écologique, induction de résistance).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-etio\">Infection urinaire</span></em></p>","frequence":1},{"id":"177-11","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) la principale molécule associant sulfaméthoxazole et triméthoprime","contenu":"<p>Le <span class=\"kw-ttt\">cotrimoxazole</span> associe <span class=\"kw-ttt\">sulfaméthoxazole</span> (sulfamide) et <span class=\"kw-ttt\">triméthoprime</span>. Il <strong>inhibe le métabolisme de l'acide folique</strong>, bactéricide, à très bonne <span class=\"kw-bio\">biodisponibilité orale</span> et <strong>bonne <span class=\"kw-def\">diffusion</span> dans la prostate et le <span class=\"kw-bio\">LCR</span></strong>.</p>\n      <ul>\n        <li><strong>Spectre :</strong> entérobactéries, <span class=\"kw-etio\">Listeria</span>, <span class=\"kw-etio\">staphylocoques</span>, <span class=\"kw-etio\">Pneumocystis jirovecii</span>.</li>\n        <li><strong>Indications :</strong> <span class=\"kw-alerte\">pneumocystose</span> (prévention et traitement) ; toxoplasmose cérébrale (en association ; la référence reste <span class=\"kw-ttt\">sulfadiazine + pyriméthamine</span>) ; infections urinaires <strong>documentées</strong>, notamment la <span class=\"kw-etio\">prostatite</span> ; alternative à l'<span class=\"kw-ttt\">amoxicilline</span> pour la <span class=\"kw-etio\">listériose</span>.</li>\n      </ul>\n      <div class=\"obj-callout\">\n        <strong>Effets indésirables &amp; CI.</strong> <span class=\"kw-clinique\">Allergie</span> (possiblement croisée avec <span class=\"kw-clinique\">les</span> autres sulfamides ; risque de <span class=\"kw-alerte\">Lyell</span>, <span class=\"kw-alerte\">DRESS</span>) ; <span class=\"kw-bio\">cytopénies</span> (anémie mégaloblastique par carence en folates) ; <span class=\"kw-ci\">insuffisance rénale</span>. Risque accru en cas de <span class=\"kw-ci\">déficit en G6PD</span>. <span class=\"kw-ci\">Contre-indiqué au 1ᵉʳ trimestre de grossesse</span> — risque de <span class=\"kw-alerte\">spina bifida</span> par carence en vitamine B9.\n      </div>","frequence":1},{"id":"177-12","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux macrolides","contenu":"<p>Molécules : <span class=\"kw-ttt\">érythromycine</span>, <span class=\"kw-ttt\">spiramycine</span>, <span class=\"kw-ttt\">clarithromycine</span>, <span class=\"kw-ttt\">azithromycine</span> (T½ longue), josamycine. Inhibition de la synthèse protéique (sous-unité <strong>50S</strong>), <strong>bactériostatiques</strong>. Administration le plus souvent <span class=\"kw-bio\">per os</span>.</p>\n      <ul>\n        <li><strong>Spectre :</strong> bactéries <span class=\"kw-def\">intracellulaires</span>, <span class=\"kw-etio\">streptocoques</span>, SAMS, <em>Toxoplasma gondii</em>.</li>\n        <li><strong>Indications :</strong> angine à <span class=\"kw-etio\">streptocoque</span> en cas d'<span class=\"kw-ci\">allergie aux β-lactamines</span> ; pneumonies à bactéries intracellulaires / atypiques (légionellose non grave) ; <strong>coqueluche</strong> ; infections à <em><span class=\"kw-clinique\">Chlamydia</span> trachomatis</em> ; infections à <em><span class=\"kw-etio\">Salmonella</span></em> / <em><span class=\"kw-etio\">Shigella</span></em> / <em><span class=\"kw-etio\">Campylobacter</span></em> (<span class=\"kw-ttt\">azithromycine</span>) ; maladie des griffes du chat ; toxoplasmose de l'immunocompétent (spiramycine).</li>\n      </ul>\n      <div class=\"obj-callout\">\n        <strong>Interactions — piège récurrent.</strong> <span class=\"kw-clinique\">Les</span> macrolides sont des <span class=\"kw-alerte\">inhibiteurs enzymatiques du CYP3A4</span> : ils majorent l'effet de la <span class=\"kw-ttt\">colchicine</span> et des <span class=\"kw-ttt\">statines</span> → <strong>arrêt temporaire des <span class=\"kw-ttt\">statines</span></strong> en cas de prescription d'un macrolide (risque de rhabdomyolyse). Autres effets : <span class=\"kw-alerte\">allongement du QT</span>, troubles digestifs, hépatites immunoallergiques.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 163 — Coqueluche</em></p>","frequence":2},{"id":"177-13","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux lincosamides","contenu":"<p>Molécule de référence : la <span class=\"kw-ttt\">clindamycine</span>. Inhibition de la synthèse protéique (sous-unité <strong>50S</strong>), bactéricide concentration-dépendant. Très bonne <span class=\"kw-bio\">biodisponibilité</span>, <strong>bonne <span class=\"kw-def\">diffusion</span> osseuse</strong>, et <span class=\"kw-def\">activité anti-toxinique</span>.</p>\n      <ul>\n        <li><strong>Spectre :</strong> <span class=\"kw-etio\">streptocoques</span>, staphylocoques, certains <span class=\"kw-etio\">anaérobies</span>, <em>Toxoplasma gondii</em>. Résistance naturelle : BGN, <em><span class=\"kw-etio\">Enterococcus</span> faecalis</em>.</li>\n        <li><strong>Indications :</strong> dermohypodermite nécrosante de la région brachio-faciale ou des membres (en association avec l'<span class=\"kw-ttt\">Augmentin</span>) ; <strong>infection ostéo-articulaire</strong> à <span class=\"kw-etio\">staphylocoque</span> sensible (en association) ; <span class=\"kw-clinique\">érysipèle</span> et prophylaxie de l'<span class=\"kw-etio\">endocardite</span> infectieuse en cas d'<span class=\"kw-ci\">allergie à l'amoxicilline</span> ; toxoplasmose cérébrale si <span class=\"kw-ci\">allergie</span> aux sulfamides.</li>\n        <li><strong>Effets indésirables :</strong> troubles digestifs, <span class=\"kw-alerte\">colite à <em>Clostridioides difficile</em></span> (<span class=\"kw-clinique\">diarrhée</span> dans ~<span class=\"kw-chiffre\">20 %</span> des cas, jusqu'à la colite pseudomembraneuse).</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 156 — Infection ostéo-articulaire · 152 — <span class=\"kw-etio\">Endocardite</span> infectieuse</em></p>","frequence":0},{"id":"177-14","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux imidazolés","contenu":"<p>Molécules : <span class=\"kw-ttt\">métronidazole</span>, secnidazole. Formation de métabolites à l'origine de <strong>lésions de l'ADN <span class=\"kw-etio\">bactérien</span></strong> ; bactéricides concentration-dépendants, très bonne <span class=\"kw-bio\">biodisponibilité orale</span>.</p>\n      <ul>\n        <li><strong>Spectre :</strong> <span class=\"kw-def\">anaérobies</span> (sauf <em>Actinomyces</em> et <em>Cutibacterium</em>) ; <em><span class=\"kw-clinique\">Helicobacter pylori</span></em> ; activité <strong><span class=\"kw-ttt\">antiparasitaire</span></strong> sur <em>Entamoeba histolytica</em>, <em>Giardia</em>, <em>Trichomonas vaginalis</em>.</li>\n        <li><strong>Indications :</strong> infections à <span class=\"kw-etio\">anaérobies</span> sensibles (digestives, génitales hautes, <span class=\"kw-clinique\">pneumopathie d'inhalation</span>) ; amœbose, giardiose, trichomonose urogénitale, vaginites non spécifiques ; colite à <em><span class=\"kw-etio\">C. difficile</span></em> non compliquée ; éradication d'<em><span class=\"kw-clinique\">H. pylori</span></em> (en association).</li>\n        <li><strong>Effets indésirables :</strong> <span class=\"kw-alerte\">effet antabuse</span> avec l'<span class=\"kw-etio\">alcool</span> ; goût métallique, glossite, stomatite ; <span class=\"kw-clinique\">neuropathie</span> sensitive ; coloration des urines.</li>\n      </ul>\n      <div class=\"obj-callout\">\n        <strong>Piège lexical.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">imidazolés</span> (antibactériens) ne doivent pas être confondus avec les <span class=\"kw-ttt\">azolés antifongiques</span> (<span class=\"kw-ttt\">fluconazole</span>, kétoconazole…) : familles distinctes, cibles différentes.\n      </div>","frequence":1},{"id":"177-15","rang":"B","rubrique":"Définition","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principales molécules appartenant aux glycopeptides","contenu":"<p>Molécules : <span class=\"kw-ttt\">vancomycine</span>, téicoplanine. Inhibition de la synthèse de la paroi par blocage du <strong>peptidoglycane</strong>. Bactéricides <strong>temps-dépendants</strong>, à bactéricidie lente.</p>\n      <ul>\n        <li><strong>Voie :</strong> <span class=\"kw-ttt\">parentérale stricte</span> — exception : la <span class=\"kw-ttt\">vancomycine per os</span>, qui n'agit qu'au niveau digestif (colite à <em><span class=\"kw-etio\">C. difficile</span></em>).</li>\n        <li><strong>Spectre :</strong> <strong>Gram positif uniquement</strong> — SASM, <span class=\"kw-etio\">SARM</span>, <span class=\"kw-etio\">streptocoque</span>, pneumocoque, <span class=\"kw-etio\">entérocoque</span>, <span class=\"kw-etio\">Listeria</span>, <em><span class=\"kw-etio\">C. difficile</span></em>. <span class=\"kw-ci\">Inactifs sur les BGN</span> (membrane externe) et <span class=\"kw-clinique\">les</span> intracellulaires.</li>\n        <li><strong>Indications :</strong> infections graves à <span class=\"kw-bio\">SARM</span>, ou à SASM en cas d'<span class=\"kw-ci\">allergie</span> aux pénicillines M / à la céfazoline ; infections graves à <span class=\"kw-etio\">streptocoque</span>/<span class=\"kw-etio\">entérocoque</span>/pneumocoque si allergie aux β-lactamines ; <span class=\"kw-clinique\">fièvre</span> du <span class=\"kw-clinique\">neutropénique</span> ; <span class=\"kw-ttt\">vancomycine</span> PO en 1ʳᵉ intention des colites à <em><span class=\"kw-etio\">C. difficile</span></em>.</li>\n      </ul>\n      <div class=\"obj-callout\">\n        <strong>Red man syndrome — à ne pas confondre avec une <span class=\"kw-ci\">allergie</span>.</strong> Une <span class=\"kw-clinique\">érythrodermie</span> apparaît lorsque la perfusion est trop rapide (&lt; <span class=\"kw-chiffre\">1 h</span>) : c'est une <strong>histamino-libération</strong>, <span class=\"kw-alerte\">pas une allergie</span> — elle ne contre-indique pas la poursuite du traitement. Autres effets : néphrotoxicité, ototoxicité, veinite.\n      </div>","frequence":1},{"id":"177-16","rang":"A","rubrique":"Définition","titre":"Citer les virus pour lesquels il existe un traitement anti-viral","contenu":"<p>Il n'existe de traitement <span class=\"kw-ttt\">antiviral</span> que pour une <strong>minorité de virus</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">VIH</span></li>\n        <li>Virus du groupe <span class=\"kw-etio\">Herpès</span> : <span class=\"kw-etio\">HSV</span>, CMV, VZV</li>\n        <li><span class=\"kw-etio\">VHB</span> et <span class=\"kw-etio\">VHC</span></li>\n        <li><span class=\"kw-etio\">Virus grippal</span></li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> antiviraux interfèrent avec une étape du <strong>cycle <span class=\"kw-etio\">viral</span> intracellulaire</strong> (en particulier la synthèse des acides nucléiques) : <span class=\"kw-alerte\">aucun n'est virucide</span> sur une particule <span class=\"kw-etio\">virale</span> extracellulaire.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Objectif thérapeutique</th><th>Virus concernés</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Contrôler la réplication</strong> au long cours</td><td><span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span></td></tr>\n          <tr><td><strong>Limiter l'intensité</strong> d'un épisode aigu</td><td>Virus du groupe <span class=\"kw-etio\">Herpès</span>, virus grippal</td></tr>\n          <tr><td><strong>Éradiquer</strong> l'infection</td><td><span class=\"kw-etio\">VHC</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 166 — Grippe</em></p>","frequence":0},{"id":"177-17","rang":"B","rubrique":"Définition","titre":"Connaître les restrictions d’utilisation des principales molécules appartenant aux carbapénèmes","contenu":"<p>Molécules : <span class=\"kw-ttt\">imipénème</span>, <span class=\"kw-ttt\">méropénème</span>, <span class=\"kw-ttt\">ertapénème</span> (T½ longue, 1 injection/24 h). <span class=\"kw-ttt\">β-lactamines</span> à voie <strong>parentérale stricte</strong>, au spectre <strong>extrêmement large</strong> (BGN multirésistants, entérobactéries, <span class=\"kw-etio\">Pseudomonas</span>, <span class=\"kw-etio\">entérocoque</span>, SAMS, anaérobies).</p>\n      <ul>\n        <li><strong>Indications restreintes :</strong> infections graves à <span class=\"kw-alerte\">bactéries multirésistantes</span> (notamment liées aux soins) ; <span class=\"kw-ttt\">antibiothérapie</span> probabiliste d'une infection suspectée à <span class=\"kw-alerte\">EBLSE</span> <strong>en présence de <span class=\"kw-alerte\">signes de gravité</span></strong>.</li>\n        <li><span class=\"kw-alerte\">Ertapénème inactif sur <em>Pseudomonas</em> et l'entérocoque</span> (résistance naturelle).</li>\n        <li><strong>Effet indésirable propre :</strong> troubles neurologiques à type de <span class=\"kw-clinique\">convulsions</span> — surtout avec l'<span class=\"kw-ttt\">imipénème</span>.</li>\n      </ul>\n      <div class=\"obj-callout\">\n        <strong>Préservation de la classe.</strong> <span class=\"kw-clinique\">Les</span> carbapénèmes sont des antibiotiques à <span class=\"kw-def\">dispensation contrôlée</span> : il faut <strong>réduire leur consommation</strong> pour préserver leur efficacité, et les <strong>arrêter dès que possible</strong> après documentation (désescalade). Les entérobactéries productrices de carbapénémases (<span class=\"kw-alerte\">EPC</span>) sont des <span class=\"kw-alerte\">BHRe</span>.\n      </div>","frequence":0},{"id":"177-18","rang":"B","rubrique":"Définition","titre":"Citer les médicaments actifs sur les virus du groupe HSV et VVZ","contenu":"<p>Pour <span class=\"kw-clinique\">les</span> infections à <span class=\"kw-etio\">HSV</span> et <span class=\"kw-etio\">VZV</span> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Aciclovir</span> (voie IV) ou <span class=\"kw-ttt\">penciclovir</span>.</li>\n        <li>Prodrogues à <strong>meilleure absorption orale</strong> : <span class=\"kw-ttt\">valaciclovir</span> (prodrogue de l'<span class=\"kw-ttt\">aciclovir</span>) et <span class=\"kw-ttt\">famciclovir</span> (prodrogue du penciclovir).</li>\n      </ul>\n      <div class=\"obj-callout info\">\n        <strong>À distinguer du <span class=\"kw-etio\">CMV</span>.</strong> <span class=\"kw-clinique\">Les</span> molécules actives sur le <span class=\"kw-etio\">cytomégalovirus</span> sont différentes : <span class=\"kw-ttt\">ganciclovir</span> IV (prodrogue orale = valganciclovir) et <span class=\"kw-ttt\">foscarnet</span> IV.\n      </div>","frequence":0},{"id":"177-19","rang":"B","rubrique":"Définition","titre":"Connaître les grands principes du traitement antirétroviral (ARV)","contenu":"<p>Le traitement <span class=\"kw-def\">antirétroviral</span> (ARV) inhibe la <strong>réplication <span class=\"kw-etio\">virale</span></strong> du <span class=\"kw-etio\">VIH</span> : il en réduit <span class=\"kw-clinique\">les</span> effets mais <span class=\"kw-alerte\">n'éradique pas l'infection</span> — son effet est uniquement <strong>suspensif</strong>.</p>\n      <ul>\n        <li><strong>Toujours en association</strong> : schéma type <span class=\"kw-ttt\">2 INTI + 1 INNTI</span>, ou <span class=\"kw-ttt\">1 IP + ritonavir</span>, ou avec un <span class=\"kw-ttt\">inhibiteur d'intégrase</span>.</li>\n        <li><strong>Cibles virales :</strong> transcriptase inverse (INTI, INNTI), protéase (IP), intégrase (II).</li>\n        <li><strong>Observance :</strong> une <span class=\"kw-alerte\">mauvaise observance expose à la résistance</span> ; pas d'interruption du traitement.</li>\n        <li>Réaliser un <span class=\"kw-bio\">génotypage</span> à la recherche de mutations de résistance <strong>avant l'instauration</strong>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":0},{"id":"177-20","rang":"A","rubrique":"Définition","titre":"Connaître les conséquences de la résistance bactérienne aux antibiotiques","contenu":"<p>Une <span class=\"kw-def\">résistance</span> mise en évidence <em>in vitro</em> implique une <span class=\"kw-alerte\">forte probabilité d'échec thérapeutique</span> clinique.</p>\n      <p><span class=\"kw-clinique\">Les</span> conséquences à l'échelle individuelle et collective :</p>\n      <ul>\n        <li><strong>Échec du traitement</strong> probabiliste et risque d'<span class=\"kw-alerte\">impasse thérapeutique</span> (plus aucune molécule active).</li>\n        <li>Recours forcé aux antibiotiques de <strong>dernière ligne</strong> (carbapénèmes), ce qui accélère leurs propres résistances.</li>\n        <li>Émergence et <span class=\"kw-def\">diffusion</span> des <span class=\"kw-alerte\">BMR</span> et des <span class=\"kw-alerte\">BHRe</span>.</li>\n        <li><span class=\"kw-alerte\">Surmortalité</span>, allongement des durées d'<span class=\"kw-alerte\">hospitalisation</span>, surcoût.</li>\n        <li>Le tout dans un contexte de <strong>rareté des nouveaux antibiotiques</strong> découverts.</li>\n      </ul>\n      <div class=\"obj-callout\">\n        <strong>À retenir.</strong> La résistance <span class=\"kw-etio\">bactérienne</span> est sélectionnée par la <span class=\"kw-def\">pression antibiotique</span> : son contrôle repose sur le bon usage des antibiotiques (cf. objectif dédié).\n      </div>","frequence":0},{"id":"177-21","rang":"A","rubrique":"Définition","titre":"Connaître la définition et principaux antibiotiques à risque générateur de résistance élevé","contenu":"<p>Un <span class=\"kw-def\">antibiotique à risque générateur de résistance élevé</span> est un antibiotique à <strong>fort impact écologique</strong> : il exerce une forte <span class=\"kw-def\">pression de sélection</span> sur <span class=\"kw-clinique\">les</span> flores commensales (tube digestif surtout, oropharynx, peau) et favorise l'émergence de souches résistantes.</p>\n      <p><span class=\"kw-clinique\">Les</span> principaux antibiotiques concernés :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Amoxicilline-acide clavulanique</span></li>\n        <li><span class=\"kw-ttt\">Céphalosporines</span> (notamment <span class=\"kw-clinique\">les</span> C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span>G</span>)</li>\n        <li><span class=\"kw-ttt\">Fluoroquinolones</span></li>\n        <li><span class=\"kw-ttt\">Carbapénèmes</span></li>\n        <li><span class=\"kw-ttt\">Témocilline</span></li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> bactéries les plus à risque de développer des résistances sont les <span class=\"kw-etio\">staphylocoques</span> et <span class=\"kw-etio\">Pseudomonas aeruginosa</span>.</p>","frequence":0},{"id":"177-22","rang":"B","rubrique":"Définition","titre":"Citer les médicaments actifs sur les virus grippaux","contenu":"<p><span class=\"kw-clinique\">Les</span> médicaments actifs sur les <span class=\"kw-etio\">virus grippaux</span> sont les <strong>inhibiteurs de la neuraminidase</strong> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Oseltamivir</span> (voie orale).</li>\n      </ul>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Usage</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Curatif</strong></td><td>Efficace si débuté &lt; <span class=\"kw-chiffre\">48 h</span> après le début des symptômes</td></tr>\n          <tr><td><strong>Prophylactique</strong></td><td>Efficace si débuté &lt; <span class=\"kw-chiffre\">48 h</span> après l'exposition ; indication élargie en cas d'épidémie en établissement d'accueil de personnes âgées</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 166 — <span class=\"kw-etio\">Grippe</span></em></p>","frequence":0},{"id":"177-23","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principes du mode d’évaluation de l’activité anti-bactérienne","contenu":"<p>Deux paramètres de laboratoire et la pharmacodynamie fondent l'évaluation de l'activité antibactérienne.</p>\n      <p><strong>Concentration minimale inhibitrice (<span class=\"kw-bio\">CMI</span>)</strong> — concentration d'antibiotique la plus basse permettant d'inhiber toute croissance <span class=\"kw-etio\">bactérienne</span> visible en <span class=\"kw-chiffre\">18-24 h</span>. <strong><span class=\"kw-bio\">CMB</span></strong> — concentration minimale bactéricide : un antibiotique est d'autant plus bactéricide que le rapport <span class=\"kw-chiffre\">CMB/CMI &lt; 4</span>.</p>\n      <p><strong><span class=\"kw-bio\">Antibiogramme</span></strong> — réalisé en routine par la méthode des disques (<span class=\"kw-clinique\">diamètre</span> d'inhibition inversement proportionnel à la <span class=\"kw-bio\">CMI</span>). La souche est classée :</p>\n      <ul>\n        <li><strong>Sensible (S)</strong> : <span class=\"kw-bio\">CMI</span> &lt; concentration critique (posologie usuelle).</li>\n        <li><strong>Intermédiaire (I)</strong> : <span class=\"kw-bio\">CMI</span> ≈ concentration critique.</li>\n        <li><strong>Résistante (R)</strong> : <span class=\"kw-bio\">CMI</span> &gt; concentration critique (posologie maximale).</li>\n      </ul>\n      <p>L'activité <span class=\"kw-def\">bactériostatique</span> (inhibition de la croissance) se distingue de l'activité <span class=\"kw-def\">bactéricide</span> (destruction). <span class=\"kw-clinique\">Les</span> bactéricides se répartissent selon leur pharmacodynamie :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th></th><th>Concentration-dépendant</th><th>Temps-dépendant</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Principe</strong></td><td>Activité optimale quand la concentration est élevée, même brièvement</td><td>Activité liée au temps passé avec une concentration &gt; <span class=\"kw-bio\">CMI</span></td></tr>\n          <tr><td><strong>Paramètre de <span class=\"kw-def\">suivi</span></strong></td><td><span class=\"kw-bio\">Pic</span> (concentration max) ; quotient inhibiteur ; aire sous la courbe / <span class=\"kw-bio\">CMI</span></td><td><span class=\"kw-bio\">Concentration résiduelle</span> (ou à l'équilibre si perfusion continue)</td></tr>\n          <tr><td><strong>Administration</strong></td><td><span class=\"kw-chiffre\">1 à 2</span> fois/jour, fortes doses</td><td>Plusieurs fois/jour, voire perfusion continue</td></tr>\n          <tr><td><strong>Exemples</strong></td><td><span class=\"kw-ttt\">Aminosides</span>, <span class=\"kw-ttt\">fluoroquinolones</span>, <span class=\"kw-ttt\">imidazolés</span></td><td><span class=\"kw-ttt\">β-lactamines</span>, <span class=\"kw-ttt\">glycopeptides</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"177-24","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux mécanismes à l’origine de la résistance","contenu":"<p>La résistance peut être <span class=\"kw-def\">naturelle</span> (présente chez toutes <span class=\"kw-clinique\">les</span> souches d'une espèce) ou <span class=\"kw-def\">acquise</span> (souche initialement sensible). Elle naît de <strong>mutations chromosomiques</strong> et d'<strong>échanges de matériel <span class=\"kw-etio\">génétique</span></strong> (plasmides, transposons), sélectionnés par la <span class=\"kw-def\">pression antibiotique</span>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Mécanisme</th><th>Description &amp; exemples</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Inactivation enzymatique</strong></td><td>Sécrétion d'enzymes détruisant l'antibiotique : <span class=\"kw-def\">β-lactamases</span> (pénicillinase, céphalosporinase, <span class=\"kw-bio\">carbapénémase</span>). Mécanisme des entérobactéries et de la résistance de <em>S. aureus</em> à l'<span class=\"kw-ttt\">amoxicilline</span></td></tr>\n          <tr><td><strong>Modification de la cible</strong></td><td>Diminution de l'affinité de la cible : <span class=\"kw-alerte\">PSDP</span> (<span class=\"kw-etio\">pneumocoque</span>, modification de la PLP) ; <span class=\"kw-etio\">SARM</span> (<em>S. aureus</em>, expression de la PLP2a → résistance à toutes <span class=\"kw-clinique\">les</span> β-lactamines)</td></tr>\n          <tr><td><strong>Diminution de la perméabilité</strong></td><td>Modification des porines de la membrane externe (ex. <em><span class=\"kw-etio\">Pseudomonas</span> aeruginosa</em>)</td></tr>\n          <tr><td><strong>Augmentation de l'efflux</strong></td><td>Expulsion active de l'antibiotique hors de la bactérie (ex. macrolide / <span class=\"kw-etio\">pneumocoque</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout info\">\n        <strong>À noter.</strong> L'<span class=\"kw-ttt\">acide clavulanique</span> est un inhibiteur de pénicillinase : couplé à une pénicilline, il en restaure l'activité — sauf si la bactérie produit une trop grande quantité d'enzyme.\n      </div>","frequence":0},{"id":"177-25","rang":"A","rubrique":"Prise en charge","titre":"Comprendre le bon usage des antibiotiques chez l’adulte","contenu":"<p>Le <span class=\"kw-def\">bon usage des antibiotiques</span> vise l'efficacité du traitement tout en limitant la pression de sélection des résistances.</p>\n      <p><strong>1. Situations ne relevant pas d'un antibiotique.</strong> Majorité des infections ORL (souvent virales : rhinopharyngite, OMA congestive, angine à <span class=\"kw-bio\">TDR</span> négatif), bronchites aiguës de l'adulte sain, situations de <span class=\"kw-def\">colonisation</span> (<span class=\"kw-clinique\">bactériurie asymptomatique</span>, plaie ou escarre colonisée).</p>\n      <p><strong>2. Avant traitement.</strong> Un <span class=\"kw-bio\">prélèvement bactériologique</span> (<span class=\"kw-bio\">hémocultures</span> ± site infecté) est envisagé systématiquement — même en cas d'infection grave. <span class=\"kw-alerte\">Seule exception : le purpura fulminans en pré-hospitalier</span>, où l'<span class=\"kw-ttt\">antibiothérapie</span> prime.</p>\n      <p><strong>3. Instauration et voie.</strong> Privilégier la <strong>voie orale</strong> chaque fois que possible. La voie <span class=\"kw-ttt\">IV</span> est requise dans le <span class=\"kw-etio\">sepsis</span> / <span class=\"kw-etio\">choc septique</span>, l'<span class=\"kw-etio\">endocardite</span>, la <span class=\"kw-etio\">méningite</span>, lorsque la voie orale est impossible, ou pour <span class=\"kw-clinique\">les</span> antibiotiques à biodisponibilité nulle (aminosides, glycopeptides, oxacilline).</p>\n      <p><strong>4. Associations d'antibiotiques — 3 utilités :</strong></p>\n      <ul>\n        <li>Élargir le <span class=\"kw-def\">spectre</span> (infections graves non documentées, plurimicrobiennes).</li>\n        <li>Augmenter la <strong>vitesse de bactéricidie</strong> par synergie (β-lactamine + aminoside).</li>\n        <li>Prévenir l'<strong>émergence de résistance</strong> (ex. <em>S. aureus</em> : pas de monothérapie de <span class=\"kw-ttt\">rifampicine</span>, d'acide fusidique, de fosfomycine).</li>\n      </ul>\n      <p><strong>5. Durée.</strong> <span class=\"kw-ttt\">Antibiothérapie</span> ≤ <span class=\"kw-chiffre\">7-10 jours</span> dans l'immense majorité des cas (exceptions : IOA, <span class=\"kw-etio\">endocardite</span>, <span class=\"kw-etio\">tuberculose</span>). <strong>Prévoir d'emblée la date d'arrêt</strong> ; <span class=\"kw-ci\">pas de posologie dégressive</span>.</p>\n      <p><strong>6. <span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">48-72 h</span>.</strong> Systématique (clinique + microbiologie). Elle permet la <span class=\"kw-def\">désescalade</span> : spectre plus étroit, bithérapie → monothérapie, voie IV → orale. Penser aux causes d'échec : microbiologique, pharmacologique, <strong>stratégique</strong> (<span class=\"kw-clinique\">abcès</span> non drainé, corps étranger).</p>\n      <p><strong>7. Politique d'établissement.</strong> Référent en <span class=\"kw-ttt\">antibiothérapie</span>, listes d'antibiotiques à <span class=\"kw-def\">dispensation contrôlée</span> (glycopeptides, carbapénèmes), référentiels, audits de prescription.</p>\n\n      <p><strong>8. <span class=\"kw-ttt\">Antibioprophylaxie</span> chirurgicale.</strong> Distincte d'une <span class=\"kw-ttt\">antibiothérapie</span> curative, elle vise à <strong>prévenir</strong> l'infection du site opératoire. Son indication dépend du type de <span class=\"kw-ttt\">chirurgie</span> selon la <span class=\"kw-def\">classification d'Altemeier</span> : elle est réservée aux gestes de <strong><span class=\"kw-chiffre\">classe 1</span> (propre)</strong> et de <strong><span class=\"kw-chiffre\">classe 2</span> (propre-contaminée)</strong>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Classe d'Altemeier</th><th><span class=\"kw-def\">Antibioprophylaxie</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">Classe 1</span></strong> — propre</td><td>Indiquée</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">Classe 2</span></strong> — propre-contaminée</td><td>Indiquée</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">Classe 3</span></strong> — contaminée</td><td>Relève d'une <span class=\"kw-ttt\">antibiothérapie</span> curative (hors <span class=\"kw-def\">antibioprophylaxie</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">Classe 4</span></strong> — sale</td><td>Relève d'une <span class=\"kw-ttt\">antibiothérapie</span> curative (hors <span class=\"kw-def\">antibioprophylaxie</span>)</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Spectre étroit</strong> ; choix de la molécule selon le type de <span class=\"kw-ttt\">chirurgie</span>, la flore endogène du patient, l'écologie du service et <span class=\"kw-clinique\">les</span> ATCD d'<span class=\"kw-ci\">allergie</span>.</li>\n        <li><strong>Voie <span class=\"kw-ttt\">IV</span> systématique</strong> (concentrations efficaces pendant toute l'intervention).</li>\n        <li>Modalités (dose, <strong>réinjections per-opératoires</strong>) selon le <span class=\"kw-chiffre\">poids</span>, la <span class=\"kw-chiffre\">demi-vie d'élimination</span> et la <span class=\"kw-chiffre\">durée de l'intervention</span>.</li>\n        <li><strong>Durée &lt; <span class=\"kw-chiffre\">24 h</span></strong> dans la majorité des cas.</li>\n      </ul>\n\n      <p><strong>9. <span class=\"kw-ttt\">Antibioprophylaxie</span> de l'<span class=\"kw-etio\">endocardite infectieuse</span> (gestes dentaires).</strong> Elle concerne <strong>uniquement</strong> <span class=\"kw-clinique\">les</span> patients porteurs d'une <span class=\"kw-alerte\">cardiopathie à haut risque d'EI</span>, et seulement avant un geste dentaire à <strong>risque de <span class=\"kw-clinique\">bactériémie</span></strong> : manipulation de la gencive ou de la région périapicale (apex dentaire, <strong>détartrage compris</strong>) ou effraction de la muqueuse.</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Amoxicilline</span> per os ou IV : <span class=\"kw-chiffre\">30-60 min</span> avant le geste.</li>\n        <li>Si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">clindamycine</span> per os ou IV, <span class=\"kw-chiffre\">30-60 min</span> avant le geste.</li>\n      </ul>\n      <div class=\"obj-callout danger\">\n        <strong>Pas d'<span class=\"kw-ttt\">antibioprophylaxie</span></strong> après un traumatisme gingival/dentaire, avant une <span class=\"kw-imagerie\">coloscopie</span>, une <span class=\"kw-ttt\">intubation</span>, ni aucune autre <span class=\"kw-ttt\">chirurgie</span>. L'<span class=\"kw-def\">éducation thérapeutique</span> (hygiène bucco-dentaire, <span class=\"kw-def\">suivi</span> dentaire : <span class=\"kw-chiffre\">2×/an</span> si haut risque, <span class=\"kw-chiffre\">1×/an</span> sinon ; carte de patient à risque d'EI) concerne en revanche <strong>toutes</strong> <span class=\"kw-clinique\">les</span> cardiopathies à risque (intermédiaire ou haut).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë · 152 — <span class=\"kw-etio\">Endocardite</span> infectieuse · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":0},{"id":"177-26","rang":"A","rubrique":"Prise en charge","titre":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principaux antifongiques utilisés pour la prise en charge des infections fongiques superficielles","contenu":"<p>Quatre grandes classes d'antifongiques existent (<span class=\"kw-ttt\">polyènes</span>, <span class=\"kw-ttt\">azolés</span>, <span class=\"kw-ttt\">échinocandines</span>, <span class=\"kw-ttt\">5-fluorocytosine</span>) ; <span class=\"kw-clinique\">les</span> <strong>infections superficielles</strong> (candidoses cutanéo-muqueuses, dermatophytoses, teignes, <span class=\"kw-etio\">pityriasis</span> versicolor, onychomycoses) relèvent surtout des molécules ci-dessous.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Molécule</th><th>Indications superficielles</th><th>Spectre utile</th><th>CI / Interactions</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Amphotéricine B</span> (topique)</td><td>Intertrigo des grands plis à <em><span class=\"kw-etio\">Candida</span></em>, candidose buccale</td><td><em><span class=\"kw-etio\">Candida</span></em></td><td><span class=\"kw-ci\">Hypersensibilité</span> ; prise séparée des topiques digestifs</td></tr>\n          <tr><td><span class=\"kw-ttt\">Nystatine</span> (locale)</td><td>Vulvo-vaginite à <em><span class=\"kw-etio\">Candida</span></em></td><td><em><span class=\"kw-etio\">Candida</span></em></td><td><span class=\"kw-ci\">Hypersensibilité</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Éconazole</span>, <span class=\"kw-ttt\">kétoconazole</span> (azolés topiques)</td><td>Intertrigos, balanite, périonyxis à <em><span class=\"kw-etio\">Candida</span></em> ; <strong><span class=\"kw-etio\">pityriasis</span> versicolor</strong> ; dermatophytoses</td><td><em><span class=\"kw-etio\">Candida</span></em>, <em><span class=\"kw-etio\">Malassezia</span></em>, dermatophytes</td><td><span class=\"kw-alerte\">↑ effet des AVK</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Fluconazole</span>, <span class=\"kw-ttt\">itraconazole</span> (azolés systémiques)</td><td>Candidoses cutanéo-muqueuses ; teignes (itraconazole)</td><td><em><span class=\"kw-etio\">Candida</span></em>, dermatophytes</td><td><span class=\"kw-ci\">CI au T1 de grossesse</span> ; allongement du QT ; <span class=\"kw-alerte\">↑ AVK</span>, <span class=\"kw-ttt\">statines</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Terbinafine</span></td><td>Teignes ; dermatophytoses ; <strong>onyxis / onychomycose</strong></td><td>Dermatophytes</td><td><span class=\"kw-alerte\">Toxicité hépatique</span> ; CI si <span class=\"kw-ci\">insuffisance hépatique</span> / rénale sévère</td></tr>\n          <tr><td><span class=\"kw-ttt\">Griséofulvine</span></td><td>Teignes ; dermatophytoses ; onyxis</td><td>Dermatophytes</td><td><span class=\"kw-ci\">CI : grossesse, lupus, insuffisance hépatique sévère, allergie à la pénicilline</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout\">\n        <strong>Deux pièges d'interaction.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">azolés</span> sont des <strong>inhibiteurs enzymatiques</strong> — nombreuses interactions, surtout <span class=\"kw-alerte\">majoration de l'effet des AVK</span>. La <span class=\"kw-ttt\">griséofulvine</span> est à l'inverse un <strong>inducteur enzymatique</strong> ; elle est <strong>fongistatique</strong> (à associer systématiquement à un <span class=\"kw-ttt\">antifongique</span> local) et reste le <strong>seul antifongique oral avec AMM chez l'enfant</strong>.\n      </div>","frequence":0},{"id":"177-27","rang":"B","rubrique":"Prise en charge","titre":"Citer les principales molécules antiparasitaires et leurs indications","contenu":"<p><span class=\"kw-clinique\">Les</span> parasites se répartissent en <span class=\"kw-def\">protozoaires</span> (unicellulaires), <span class=\"kw-def\">plathelminthes</span> (vers plats : trématodes, cestodes) et <span class=\"kw-def\">nématodes</span> (vers ronds).</p>\n      <p><strong>Protozoaires :</strong></p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Infection</th><th>Molécule</th></tr></thead>\n        <tbody>\n          <tr><td>Amœbose, giardiose, trichomonose</td><td><span class=\"kw-ttt\">Métronidazole</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Paludisme</span> non grave</td><td><span class=\"kw-ttt\">ACT</span> (ex. artéméther-luméfantrine), atovaquone-proguanil</td></tr>\n          <tr><td><span class=\"kw-alerte\">Paludisme grave</span></td><td><span class=\"kw-ttt\">Artésunate IV</span></td></tr>\n          <tr><td>Toxoplasmose (femme enceinte / immunocompétent)</td><td><span class=\"kw-ttt\">Spiramycine</span></td></tr>\n          <tr><td>Toxoplasmose cérébrale</td><td><span class=\"kw-ttt\">Pyriméthamine + sulfadiazine</span></td></tr>\n          <tr><td>Leishmaniose viscérale</td><td><span class=\"kw-ttt\">Amphotéricine B liposomale</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Helminthes</strong> (vers) :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Molécule</th><th>Principales indications</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Albendazole</span> / <span class=\"kw-ttt\">flubendazole</span></td><td>Oxyurose, ascaridiose, ankylostomose ; hydatidose et échinococcose (albendazole)</td></tr>\n          <tr><td><span class=\"kw-ttt\">Praziquantel</span></td><td>Schistosomiose, distomatose, tæniose, cysticercose</td></tr>\n          <tr><td><span class=\"kw-ttt\">Ivermectine</span></td><td>Strongyloïdose, onchocercose, larva migrans</td></tr>\n          <tr><td><span class=\"kw-ttt\">Diéthylcarbamazine</span></td><td>Filarioses (loase, filarioses lymphatiques)</td></tr>\n        </tbody>\n      </table>\n      <p>Pour le <span class=\"kw-clinique\">paludisme</span> : autres antipaludéens cités — <span class=\"kw-ttt\">quinine</span>, <span class=\"kw-ttt\">chloroquine</span>, <span class=\"kw-ttt\">méfloquine</span>, <span class=\"kw-ttt\">doxycycline</span> (<span class=\"kw-def\">chimioprophylaxie</span>).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span class=\"kw-clinique\">Paludisme</span></em></p>","frequence":2},{"id":"177-28","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les bactéries les plus fréquentes au cours des infections de l’enfant","contenu":"<p>L'<span class=\"kw-bio\">examen direct au Gram</span> oriente le diagnostic en moins d'<span class=\"kw-chiffre\">1 h</span>. <span class=\"kw-clinique\">Les</span> bactéries les plus fréquentes des infections de l'enfant :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Catégorie au Gram</th><th>Bactéries</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cocci Gram positif</strong></td><td><span class=\"kw-etio\">Streptocoque</span> (diplocoques en chaînettes) ; <span class=\"kw-etio\">pneumocoque</span> (diplocoques lancéolés) ; <span class=\"kw-etio\">staphylocoque</span> (diplocoques en amas)</td></tr>\n          <tr><td><strong>Cocci Gram négatif</strong></td><td><span class=\"kw-etio\">Méningocoque</span> (diplocoques en « grain de café »)</td></tr>\n          <tr><td><strong>Bacilles Gram négatif</strong></td><td>Entérobactéries (<em><span class=\"kw-etio\">E. coli</span></em>, <em><span class=\"kw-etio\">Klebsiella</span></em>, salmonelles) ; <em><span class=\"kw-etio\">Haemophilus</span> influenzae</em> ; <em>Bordetella pertussis</em></td></tr>\n          <tr><td><strong>Bacilles Gram positif</strong></td><td><span class=\"kw-etio\">Listeria monocytogenes</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Fréquence de positivité des <span class=\"kw-bio\">hémocultures</span></strong> : <span class=\"kw-etio\">méningite</span> à <span class=\"kw-etio\">méningocoque</span> ~<span class=\"kw-chiffre\">40 %</span>, à <span class=\"kw-etio\">pneumocoque</span> ~<span class=\"kw-chiffre\">75 %</span> ; <span class=\"kw-etio\">pyélonéphrite</span> du nourrisson ≤ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> mois</span> ~<span class=\"kw-chiffre\">10 %</span> ; pneumonies &lt; <span class=\"kw-chiffre\">10 %</span>.</p>","frequence":0},{"id":"177-29","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prescription d’une antibiothérapie chez le nourrisson et l’enfant","contenu":"<p>Comme chez l'adulte, l'<span class=\"kw-ttt\">antibiothérapie</span> n'est prescrite que devant une infection <strong><span class=\"kw-etio\">bactérienne</span></strong> avérée. Plusieurs situations pédiatriques fréquentes <strong>ne relèvent pas</strong> d'un antibiotique :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Rhinopharyngite aiguë</span>.</li>\n        <li>OMA congestive ou séro-muqueuse.</li>\n        <li>Angine aiguë à <span class=\"kw-bio\">TDR négatif</span>, ou chez l'enfant de moins de <span class=\"kw-chiffre\">3 ans</span>.</li>\n        <li>Rhino-sinusite maxillaire (signes bilatéraux diffus modérés, rhinorrhée séreuse, peu fébrile).</li>\n        <li><span class=\"kw-clinique\">Bronchiolite aiguë</span> en l'absence de signe de surinfection <span class=\"kw-etio\">bactérienne</span>.</li>\n        <li><span class=\"kw-clinique\">Diarrhée</span> aiguë liquidienne peu fébrile.</li>\n      </ul>\n      <p><strong>Modalités :</strong> privilégier la <strong>voie orale</strong> ; posologie adaptée au <span class=\"kw-chiffre\">poids</span> (mg/kg) ; choisir une molécule à spectre adapté (l'<span class=\"kw-ttt\">amoxicilline</span> couvre de nombreuses indications pédiatriques) ; tenir compte des <span class=\"kw-ci\">contre-indications</span> liées à l'âge (<span class=\"kw-ttt\">fluoroquinolones</span> et <span class=\"kw-ci\">cyclines avant 8 ans</span>).</p>\n      <div class=\"obj-callout warning\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources du dossier <code>177-mdc-anti-<span class=\"kw-etio\">infectieux</span>/</code> ne détaillent que partiellement les protocoles d'<span class=\"kw-ttt\">antibiothérapie</span> par pathologie chez l'enfant. Kevin enrichira ce paragraphe depuis le Pilly / le Collège de pédiatrie.\n      </div>","frequence":0},{"id":"177-30","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de prescription d’une antibiothérapie chez le nouveau-né","contenu":"<p>Le <span class=\"kw-def\">nouveau-né</span> est un <span class=\"kw-def\">terrain</span> à part : immaturité hépatique et rénale, barrière hémato-encéphalique perméable, risque <span class=\"kw-etio\">infectieux</span> materno-fœtal. Quelques <span class=\"kw-ci\">contre-indications</span> repérables dans <span class=\"kw-clinique\">les</span> sources : le <span class=\"kw-ttt\">cotrimoxazole</span> et les <span class=\"kw-ttt\">fluoroquinolones</span> sont contre-indiqués chez le nouveau-né (&lt; <span class=\"kw-chiffre\">6 semaines</span> pour les FQ).</p>\n      <div class=\"obj-callout warning\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> fiches sources du dossier <code>177-mdc-anti-<span class=\"kw-etio\">infectieux</span>/</code> ne détaillent pas les modalités spécifiques de prescription d'une <span class=\"kw-ttt\">antibiothérapie</span> chez le nouveau-né. Kevin enrichira ce paragraphe depuis le Pilly / le Collège de pédiatrie.\n      </div>","frequence":0},{"id":"177-31","rang":"A","rubrique":"Prise en charge","titre":"Comprendre le bon usage des antibiotiques chez l’enfant","contenu":"<p>Le bon usage chez l'enfant reprend <span class=\"kw-clinique\">les</span> principes de l'adulte (réserver l'antibiotique aux infections bactériennes, durée courte, <span class=\"kw-def\">réévaluation</span>, voie orale privilégiée) appliqués aux situations pédiatriques — beaucoup d'infections ORL et respiratoires de l'enfant étant <strong>virales</strong>.</p>\n      <p>Une dimension propre : la gestion de l'<span class=\"kw-def\">éviction de la collectivité</span>, qui dépend de la pathologie et du délai depuis le début du traitement.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Délai d'éviction</th><th>Pathologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> jours</span></strong> d'antibiotique</td><td>Angine streptococcique ; scarlatine</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> jours</span></strong></td><td><span class=\"kw-etio\">Gale</span> commune ; <span class=\"kw-clinique\">impétigo</span> (étendu)</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> jours</span></strong></td><td>Coqueluche (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> jours</span> si <span class=\"kw-ttt\">azithromycine</span>) ; rougeole</td></tr>\n          <tr><td>Jusqu'à <strong>guérison</strong></td><td><span class=\"kw-etio\">Méningite</span> à <span class=\"kw-etio\">méningocoque</span></td></tr>\n          <tr><td><strong>Pas d'éviction</strong></td><td>Bronchiolite, rhinopharyngite, <span class=\"kw-etio\">grippe</span> saisonnière, varicelle, <span class=\"kw-etio\">méningite</span> <span class=\"kw-etio\">virale</span> ou à <span class=\"kw-etio\">pneumocoque</span>, oreillons</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 163 — Coqueluche</em></p>","frequence":0},{"id":"177-32","rang":"B","rubrique":"Suivi et/ou Pronostic","titre":"Connaître les modalités de surveillance de l’enfant sous antibiothérapie","contenu":"<p>La <span class=\"kw-def\">surveillance</span> de l'enfant sous <span class=\"kw-ttt\">antibiothérapie</span> porte sur :</p>\n      <ul>\n        <li><strong>Efficacité</strong> : régression de la <span class=\"kw-clinique\">fièvre</span> et des signes <span class=\"kw-etio\">infectieux</span> ; <span class=\"kw-def\">réévaluation</span> systématique.</li>\n        <li><strong>Tolérance</strong> : recherche des effets indésirables propres à la classe prescrite.</li>\n        <li><strong>Éviction de la collectivité</strong> selon la pathologie (cf. objectif Bon usage chez l'enfant).</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Dépistage</span> des bactéries hautement résistantes (BHR)</strong> — <span class=\"kw-etio\">entérocoques</span> résistants à la <span class=\"kw-ttt\">vancomycine</span> (<span class=\"kw-alerte\">ERV</span>) et entérobactéries productrices de carbapénémases (<span class=\"kw-alerte\">EPC</span>) :</p>\n      <ul>\n        <li><strong>Qui dépister :</strong> ATCD d'<span class=\"kw-alerte\">hospitalisation</span> en zone à risque &lt; <span class=\"kw-chiffre\">12 mois</span> ; antibiothérapies multiples et prolongées. <span class=\"kw-def\">Dépistage</span> dès l'admission.</li>\n        <li><strong>Mesures d'<span class=\"kw-def\">isolement</span> :</strong> chambre individuelle, <span class=\"kw-def\">précautions contact</span> (gants, hygiène des mains, sur-blouse), implication des parents, <span class=\"kw-def\">signalement</span> interne et aux autorités sanitaires.</li>\n      </ul>\n      <div class=\"obj-callout warning\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> modalités fines de <span class=\"kw-def\">surveillance</span> <span class=\"kw-ttt\">biologique</span> de l'enfant sous <span class=\"kw-ttt\">antibiothérapie</span> sont peu détaillées dans les fiches sources — Kevin pourra enrichir depuis le Collège de pédiatrie.\n      </div>","frequence":0}],"astuces":[],"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-177.pdf","label":"infectiologie.com"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/42.%20Antibioth%C3%A9rapie%20d%27urgence.pdf","label":"ce-mir.fr"}],"cards":[{"i":"53ecc8c6e841","n":177,"o":"177-1","u":"Définition","t":"Connaître la définition d’un antibiotique","q":"Quels sont les deux modes d'action possibles d'un antibiotique sur les bactéries ?","a":"<ul><li><strong>Inhiber la croissance bactérienne</strong> (effet <strong>bactériostatique</strong>).</li><li><strong>Détruire la bactérie</strong> (effet <strong>bactéricide</strong>).</li></ul>"},{"i":"741734a549d0","n":177,"o":"177-1","u":"Définition","t":"Connaître la définition d’un antibiotique","q":"Sur quels types d'agents infectieux un antibiotique est-il actif ?","a":"<p>Un antibiotique est <strong>actif uniquement sur les bactéries</strong>. Il est inactif sur les virus, les champignons et les parasites.</p>"},{"i":"d104a880ea55","n":177,"o":"177-1","u":"Définition","t":"Connaître la définition d’un antibiotique","q":"Quelles sont les deux familles d'antibiotiques entièrement synthétiques mentionnées dans le cours ?","a":"<p>Les deux familles d'antibiotiques entièrement synthétiques sont les <strong>quinolones</strong> et les <strong>sulfamides</strong>.</p>"},{"i":"e30b142ba35f","n":177,"o":"177-1","u":"Définition","t":"Connaître la définition d’un antibiotique","q":"Quelle est la définition d'un antibiotique ?","a":"<p>Un antibiotique est une <strong>substance</strong> d'origine naturelle (produite par des champignons ou des bactéries) ou synthétique, capable d'agir sur les bactéries.</p>"},{"i":"4c3f60182774","n":177,"o":"177-16","u":"Définition","t":"Citer les virus pour lesquels il existe un traitement anti-viral","q":"Quel est l'objectif thérapeutique des anti-viraux dans les infections par les virus du groupe Herpès et par le virus grippal ?","a":"<p>Dans les infections par les <strong>virus du groupe Herpès</strong> et par le <strong>virus grippal</strong>, l'objectif thérapeutique des anti-viraux est de <strong>limiter l'intensité d'un épisode aigu</strong>.</p>"},{"i":"58f06f2d0026","n":177,"o":"177-16","u":"Définition","t":"Citer les virus pour lesquels il existe un traitement anti-viral","q":"Pour quelle infection virale majeure, le traitement antiviral vise-t-il l'éradication ?","a":"<p>Le traitement antiviral vise l'<strong>éradication de l'infection</strong> pour le <strong>VHC</strong> (Virus de l'Hépatite C).</p>"},{"i":"6b045fd71520","n":177,"o":"177-16","u":"Définition","t":"Citer les virus pour lesquels il existe un traitement anti-viral","q":"Quel est le mécanisme d'action général des traitements anti-viraux et leur effet sur les particules virales extracellulaires ?","a":"<p>Les anti-viraux interfèrent avec une étape du <strong>cycle viral intracellulaire</strong>, particulièrement la <strong>synthèse des acides nucléiques</strong>. Aucun anti-viral n'est <strong>virucide</strong> sur une particule virale extracellulaire.</p>"},{"i":"7a3bd970fc2d","n":177,"o":"177-16","u":"Définition","t":"Citer les virus pour lesquels il existe un traitement anti-viral","q":"Quel est l'objectif thérapeutique principal des traitements anti-viraux pour le VIH et le VHB ?","a":"<p>Pour le <strong>VIH</strong> et le <strong>VHB</strong>, l'objectif thérapeutique principal des anti-viraux est de <strong>contrôler la réplication virale au long cours</strong>.</p>"},{"i":"92cebaa67c9e","n":177,"o":"177-16","u":"Définition","t":"Citer les virus pour lesquels il existe un traitement anti-viral","q":"Actuellement, pour quels virus majeurs dispose-t-on de traitements anti-viraux spécifiques en médecine humaine ?","a":"<p>Il existe des traitements anti-viraux pour une minorité de virus, notamment :</p><ul><li>Le <strong>VIH</strong> (Virus de l'Immunodéficience Humaine)</li><li>Les virus du groupe <strong>Herpès</strong> : <strong>HSV</strong> (Herpes Simplex Virus), <strong>CMV</strong> (Cytomégalovirus), <strong>VZV</strong> (Varicella Zoster Virus)</li><li>Le <strong>VHB</strong> (Virus de l'Hépatite B)</li><li>Le <strong>VHC</strong> (Virus de l'Hépatite C)</li><li>Le <strong>virus grippal</strong></li></ul>"},{"i":"1361956750a4","n":177,"o":"177-2","u":"Définition","t":"Connaître la définition du spectre antibactérien","q":"Quelle est la définition du spectre antibactérien d'un antibiotique ?","a":"<p>Le <strong>spectre antibactérien</strong> d'un antibiotique représente l'ensemble des espèces bactériennes sur lesquelles l'antibiotique est <strong>actif</strong>.</p>"},{"i":"32eec4c4bef1","n":177,"o":"177-2","u":"Définition","t":"Connaître la définition du spectre antibactérien","q":"Comment le spectre antibactérien peut-il être influencé ?","a":"<ul><li>Il est <strong>borné</strong> par les <strong>résistances naturelles</strong> (présentes chez toutes les souches d'une espèce).</li><li>Il est <strong>amputé</strong> par les <strong>résistances acquises</strong> (développées par certaines souches).</li></ul>"},{"i":"98231e462d11","n":177,"o":"177-2","u":"Définition","t":"Connaître la définition du spectre antibactérien","q":"Quel examen permet de mesurer le niveau de sensibilité d'une souche bactérienne spécifique face aux antibiotiques ?","a":"<p>L'<strong>antibiogramme</strong> est l'examen qui permet de mesurer le niveau de sensibilité d'une souche bactérienne donnée face à différents antibiotiques.</p>"},{"i":"aeb7bde0b292","n":177,"o":"177-2","u":"Définition","t":"Connaître la définition du spectre antibactérien","q":"Comment évalue-t-on l'efficacité d'un antibiotique <em>in vitro</em> ?","a":"<p>L'efficacité <em>in vitro</em> est évaluée par la <strong>concentration minimale inhibitrice (CMI)</strong>. C'est la concentration la plus basse de l'antibiotique qui permet d'inhiber la croissance bactérienne aux posologies usuelles.</p>"},{"i":"c59bd4a56730","n":177,"o":"177-2","u":"Définition","t":"Connaître la définition du spectre antibactérien","q":"Quelles sont les différentes notions de spectre antibactérien d'un antibiotique ?","a":"<ul><li>Le <strong>spectre étroit</strong> cible peu d'espèces bactériennes, contrairement au <strong>spectre large</strong>.</li><li>Le <strong>spectre théorique</strong> correspond à l'activité intrinsèque de la molécule.</li><li>Le <strong>spectre utile</strong> correspond aux bactéries pour lesquelles l'antibiotique présente un intérêt clinique réel.</li></ul>"},{"i":"460372ead532","n":177,"o":"177-20","u":"Définition","t":"Connaître les conséquences de la résistance bactérienne aux antibiotiques","q":"Quelles sont les conséquences collectives de la résistance bactérienne aux antibiotiques ?","a":"<ul><li>Émergence et diffusion des <strong>Bactéries Multi-Résistantes (BMR)</strong> et des <strong>Bactéries Hautement Résistantes émergentes (BHRe)</strong>.</li><li><strong>Surcoût</strong> pour le système de santé.</li><li>Aggravation du problème dans un contexte de <strong>rareté de nouveaux antibiotiques</strong> découverts.</li></ul>"},{"i":"893e86162653","n":177,"o":"177-20","u":"Définition","t":"Connaître les conséquences de la résistance bactérienne aux antibiotiques","q":"Quelle est l'implication d'une résistance bactérienne in vitro mise en évidence pour la prise en charge clinique du patient ?","a":"<p>Une résistance bactérienne mise en évidence <em>in vitro</em> implique une <strong>forte probabilité d'échec thérapeutique clinique</strong>.</p>"},{"i":"b93992675e25","n":177,"o":"177-20","u":"Définition","t":"Connaître les conséquences de la résistance bactérienne aux antibiotiques","q":"Quelles sont les conséquences individuelles de la résistance bactérienne aux antibiotiques ?","a":"<ul><li><strong>Échec du traitement probabiliste</strong>.</li><li>Risque d'<strong>impasse thérapeutique</strong> (plus aucune molécule active).</li><li>Recours forcé aux <strong>antibiotiques de dernière ligne</strong> (ex: carbapénèmes), ce qui accélère l'émergence de leurs propres résistances.</li><li><strong>Surmortalité</strong> et <strong>allongement de la durée d'hospitalisation</strong>.</li></ul>"},{"i":"e3e0b39e54c8","n":177,"o":"177-20","u":"Définition","t":"Connaître les conséquences de la résistance bactérienne aux antibiotiques","q":"Quel est le principal facteur favorisant la sélection de la résistance bactérienne aux antibiotiques ?","a":"<p>La résistance bactérienne est principalement sélectionnée par la <strong>pression antibiotique</strong>.</p>"},{"i":"175acad2ef75","n":177,"o":"177-21","u":"Définition","t":"Connaître la définition et principaux antibiotiques à risque générateur de résistance élevé","q":"Quelles sont les bactéries les plus à risque de développer des résistances aux antibiotiques à fort impact écologique ?","a":"<ul><li>Les <strong>staphylocoques</strong></li><li><em><strong>Pseudomonas aeruginosa</strong></em></li></ul>"},{"i":"d7c98c8a533c","n":177,"o":"177-21","u":"Définition","t":"Connaître la définition et principaux antibiotiques à risque générateur de résistance élevé","q":"Quels sont les principaux antibiotiques considérés comme à risque élevé d'induction de résistance ?","a":"<ul><li><strong>Amoxicilline-acide clavulanique</strong></li><li><strong>Céphalosporines</strong> (en particulier les <3<sup>e</sup> génération)</li><li><strong>Fluoroquinolones</strong></li><li><strong>Carbapénèmes</strong></li><li><strong>Témocilline</strong></li></ul>"},{"i":"dd8e7e78e703","n":177,"o":"177-21","u":"Définition","t":"Connaître la définition et principaux antibiotiques à risque générateur de résistance élevé","q":"Quelle est la définition d'un antibiotique à risque générateur de résistance élevé ?","a":"<p>Un antibiotique à risque générateur de résistance élevé est un antibiotique à <strong>fort impact écologique</strong>. Cela signifie qu'il exerce une <strong>forte pression de sélection</strong> sur les flores commensales (notamment du tube digestif, de l'oropharynx et de la peau), favorisant ainsi l'émergence de souches bactériennes résistantes.</p>"},{"i":"49be0891aedc","n":177,"o":"177-25","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’adulte","q":"Dans quel contexte et pour quels types de chirurgie l'antibioprophylaxie chirurgicale est-elle indiquée selon la classification d'Altemeier ?","a":"<p>L'antibioprophylaxie chirurgicale vise à prévenir l'infection du site opératoire et est indiquée selon la classification d'Altemeier :</p><ul><li>Pour les gestes de <strong>classe 1 (propre)</strong>.</li><li>Pour les gestes de <strong>classe 2 (propre-contaminée)</strong>.</li></ul><p>Elle n'est pas indiquée pour les classes 3 (contaminée) et 4 (sale), qui relèvent d'une antibiothérapie curative.</p>"},{"i":"a17cee1c1ead","n":177,"o":"177-25","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’adulte","q":"Quelles sont les règles essentielles concernant la durée d'une antibiothérapie et la posologie ?","a":"<p>Les règles essentielles sont les suivantes :</p><ul><li>L'antibiothérapie doit être de <strong>≤ 7-10 jours</strong> dans l'immense majorité des cas (les exceptions incluent les infections ostéoarticulaires, l'endocardite et la tuberculose).</li><li>La <strong>date d'arrêt</strong> doit être prévue d'emblée.</li><li>Il ne faut pas réaliser de <strong>posologie dégressive</strong>.</li></ul>"},{"i":"aa8def7c5071","n":177,"o":"177-25","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’adulte","q":"Quand faut-il systématiquement envisager un prélèvement bactériologique avant d'initier une antibiothérapie, et quelle est l'exception principale ?","a":"<p>Un <strong>prélèvement bactériologique</strong> (hémocultures ± site infecté) doit être envisagé systématiquement avant toute antibiothérapie, même en cas d'infection grave.</p><p>L'unique exception est le <strong>purpura fulminans</strong> en pré-hospitalier, où l'antibiothérapie prime avant d'éventuels prélèvements.</p>"},{"i":"b19b6efdc8d5","n":177,"o":"177-25","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’adulte","q":"Quelles sont les trois principales utilités de l'association d'antibiotiques ?","a":"<p>L'association d'antibiotiques présente trois utilités principales :</p><ul><li><strong>Élargir le spectre</strong> : dans les infections graves non documentées ou plurimicrobiennes.</li><li><strong>Augmenter la vitesse de bactéricidie</strong> par synergie (ex: β-lactamine + aminoside).</li><li><strong>Prévenir l'émergence de résistance</strong> (ex: ne pas faire de monothérapie de rifampicine, acide fusidique ou fosfomycine sur <em>S. aureus</em>).</li></ul>"},{"i":"bacbdb0024b0","n":177,"o":"177-25","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’adulte","q":"Quelles sont les modalités de réevaluation systématique d'une antibiothérapie après 48-72 heures ?","a":"<p>La réévaluation systématique à <strong>48-72 heures</strong> est à la fois <strong>clinique et microbiologique</strong>. Elle permet :</p><ul><li>La <strong>désescalade</strong> : passer à un spectre plus étroit, d'une bithérapie à une monothérapie, ou d'une voie IV à une voie orale.</li><li>De rechercher les causes d'un éventuel échec : microbiologique, pharmacologique ou stratégique (par exemple, un abcès non drainé ou un corps étranger).</li></ul>"},{"i":"d1e1c971246a","n":177,"o":"177-25","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’adulte","q":"Quelles sont les modalités pratiques de l'antibioprophylaxie de l'endocardite infectieuse lors de gestes dentaires ?","a":"<p>L'antibioprophylaxie de l'endocardite infectieuse est réservée aux patients porteurs d'une <strong>cardiopathie à haut risque d'EI</strong> et seulement avant un geste dentaire à risque de bactériémie (manipulation de la gencive, région périapicale, effraction de la muqueuse). Les modalités sont :</p><ul><li><strong>Amoxicilline</strong> per os ou IV : <strong>30-60 minutes avant</strong> le geste.</li><li>En cas d'allergie : <strong>Clindamycine</strong> per os ou IV, <strong>30-60 minutes avant</strong> le geste.</li></ul><p>Il n'y a pas d'antibioprophylaxie pour d'autres situations comme un traumatisme gingival/dentaire, une coloscopie ou une intubation.</p>"},{"i":"d5a2339fe683","n":177,"o":"177-25","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’adulte","q":"Dans quelles situations courantes, bien que d'origine infectieuse, l'antibiothérapie n'est-elle généralement pas justifiée chez l'adulte ?","a":"<p>Une antibiothérapie n'est généralement pas justifiée dans les situations suivantes :</p><ul><li>La majorité des <strong>infections ORL</strong> (rhinopharyngite, otite moyenne aiguë congestive, angine à TDR négatif) car majoritairement virales.</li><li>Les <strong>bronchites aiguës de l'adulte sain</strong>.</li><li>Les situations de colonisation bactérienne asymptomatique, telles que la <strong>bactériurie asymptomatique</strong> ou une <strong>plaie/escarre colonisée</strong>.</li></ul>"},{"i":"19b375c11127","n":177,"o":"177-26","u":"Prise en charge","t":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principaux antifongiques utilisés pour la prise en charge des infections fongiques superficielles","q":"Quelles sont les principales indications du fluconazole et de l'itraconazole (azolés systémiques) dans les infections fongiques superficielles, et quelles sont leurs contre-indications majeures ?","a":"<p>Les azolés systémiques sont indiqués pour :</p><ul><li>Les <strong>candidoses cutanéo-muqueuses</strong> (fluconazole, itraconazole)</li><li>Les <strong>teignes</strong> (itraconazole)</li></ul><p>Les contre-indications majeures incluent la grossesse au <strong>T1</strong>, l'allongement du <strong>QT</strong>, et des interactions avec les <strong>AVK</strong> et les <strong>statines</strong>.</p>"},{"i":"253b24df75f7","n":177,"o":"177-26","u":"Prise en charge","t":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principaux antifongiques utilisés pour la prise en charge des infections fongiques superficielles","q":"Quelles sont les quatre grandes classes d'antifongiques couramment utilisées ?","a":"<p>Les quatre grandes classes d'antifongiques sont :</p><ul><li>Les <strong>polyènes</strong></li><li>Les <strong>azolés</strong></li><li>Les <strong>échinocandines</strong></li><li>La <strong>5-fluorocytosine</strong></li></ul>"},{"i":"7a01b3083b37","n":177,"o":"177-26","u":"Prise en charge","t":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principaux antifongiques utilisés pour la prise en charge des infections fongiques superficielles","q":"Quelles sont les contre-indications de la terbinafine et de la griséofulvine ?","a":"<p>Pour la <strong>terbinafine</strong> :</p><ul><li><strong>Toxicité hépatique</strong></li><li>Contre-indiquée en cas d'<strong>insuffisance hépatique ou rénale sévère</strong></li></ul><p>Pour la <strong>griséofulvine</strong> :</p><ul><li><strong>Grossesse</strong></li><li><strong>Lupus</strong></li><li><strong>Insuffisance hépatique sévère</strong></li><li><strong>Allergie à la pénicilline</strong></li></ul>"},{"i":"98792a15a863","n":177,"o":"177-26","u":"Prise en charge","t":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principaux antifongiques utilisés pour la prise en charge des infections fongiques superficielles","q":"Quel est le spectre d'activité des azolés topiques (éconazole, kétoconazole) dans les infections fongiques superficielles et quelle est leur principale interaction médicamenteuse ?","a":"<p>Le spectre d'activité des azolés topiques couvre <strong>Candida</strong>, <strong>Malassezia</strong> et les <strong>dermatophytes</strong>. Leur principale interaction médicamenteuse est une augmentation de l'effet des <strong>AVK</strong> (Anti-Vitamine K).</p>"},{"i":"b641ed0210cb","n":177,"o":"177-26","u":"Prise en charge","t":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principaux antifongiques utilisés pour la prise en charge des infections fongiques superficielles","q":"Quelles sont les indications principales de la terbinafine et de la griséofulvine dans les infections fongiques superficielles, et quel est leur spectre d'activité ?","a":"<p>La <strong>terbinafine</strong> est indiquée pour les <strong>teignes</strong>, les <strong>dermatophytoses</strong> et l'<strong>onyxis/onychomycose</strong>. Elle agit spécifiquement sur les <strong>dermatophytes</strong>.</p><p>La <strong>griséofulvine</strong> est indiquée pour les <strong>teignes</strong>, les <strong>dermatophytoses</strong> et l'<strong>onyxis</strong>. Elle agit également sur les <strong>dermatophytes</strong>.</p>"},{"i":"bc663fabbe3e","n":177,"o":"177-26","u":"Prise en charge","t":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principaux antifongiques utilisés pour la prise en charge des infections fongiques superficielles","q":"Quelles sont les indications des azolés topiques (éconazole, kétoconazole) dans les infections fongiques superficielles ?","a":"<p>Les azolés topiques sont indiqués pour :</p><ul><li>Les <strong>intertrigos</strong></li><li>La <strong>balanite</strong></li><li>Le <strong>périonyxis à Candida</strong></li><li>Le <strong>pityriasis versicolor</strong></li><li>Les <strong>dermatophytoses</strong></li></ul>"},{"i":"fcac5705fa84","n":177,"o":"177-26","u":"Prise en charge","t":"Connaître (indications, contre-indications, spectre, effets secondaires et interactions) les principaux antifongiques utilisés pour la prise en charge des infections fongiques superficielles","q":"Quel est un piège classique concernant les interactions médicamenteuses des antifongiques, notamment les azolés et la griséofulvine ?","a":"<p>Les <strong>azolés</strong> sont des <strong>inhibiteurs enzymatiques</strong>, entraînant de nombreuses interactions, notamment une <strong>majoration de l'effet des AVK</strong>.</p><p>La <strong>griséofulvine</strong> est, à l'inverse, un <strong>inducteur enzymatique</strong>. Elle est également <strong>fongistatique</strong> et doit être associée systématiquement à un antifongique local. C'est le seul antifongique oral avec AMM chez l'enfant.</p>"},{"i":"15e458d6d25d","n":177,"o":"177-28","u":"Epidémiologie","t":"Connaître les bactéries les plus fréquentes au cours des infections de l’enfant","q":"Quelle est la principale bactérie Bacille Gram positif fréquemment rencontrée dans les infections de l'enfant ?","a":"<p>La principale bactérie Bacille Gram positif est <em><strong>Listeria monocytogenes</strong></em>.</p>"},{"i":"70094dff8434","n":177,"o":"177-28","u":"Epidémiologie","t":"Connaître les bactéries les plus fréquentes au cours des infections de l’enfant","q":"Quelle est la fréquence de positivité des hémocultures en cas de pyélonéphrite du nourrisson de plus de 3 mois et en cas de pneumonie chez l'enfant ?","a":"<ul><li>En cas de pyélonéphrite du nourrisson <strong>≥ 3 mois</strong> : environ <strong>10 %</strong>.</li><li>En cas de pneumonie : <strong>&lt; 10 %</strong>.</li></ul>"},{"i":"70b8aab551b4","n":177,"o":"177-28","u":"Epidémiologie","t":"Connaître les bactéries les plus fréquentes au cours des infections de l’enfant","q":"Quelle est la valeur de l'examen direct au Gram dans le diagnostic des infections chez l'enfant ?","a":"<p>L'examen direct au Gram permet une <strong>orientation diagnostique rapide</strong> (en moins d'1 heure) en identifiant la morphologie et la coloration des bactéries.</p>"},{"i":"76329c64d0a2","n":177,"o":"177-28","u":"Epidémiologie","t":"Connaître les bactéries les plus fréquentes au cours des infections de l’enfant","q":"Quelles sont les principales bactéries Gram négatif fréquentes dans les infections de l'enfant et leurs caractéristiques morphologiques ?","a":"<ul><li><strong>Cocci Gram négatif</strong> : <ul><li><strong>Méningocoque</strong> : diplocoques en « <strong>grain de café</strong> ».</li></ul></li><li><strong>Bacilles Gram négatif</strong> : <ul><li><strong>Entérobactéries</strong> (<em>E. coli</em>, <em>Klebsiella</em>, salmonelles).</li><li><em>Haemophilus influenzae</em>.</li><li><em>Bordetella pertussis</em>.</li></ul></li></ul>"},{"i":"93bd4335aeef","n":177,"o":"177-28","u":"Epidémiologie","t":"Connaître les bactéries les plus fréquentes au cours des infections de l’enfant","q":"Quelle est la fréquence de positivité des hémocultures pour la méningite à méningocoque et à pneumocoque chez l'enfant ?","a":"<ul><li>Pour la méningite à méningocoque : environ <strong>40 %</strong>.</li><li>Pour la méningite à pneumocoque : environ <strong>75 %</strong>.</li></ul>"},{"i":"ee3b24a8e037","n":177,"o":"177-28","u":"Epidémiologie","t":"Connaître les bactéries les plus fréquentes au cours des infections de l’enfant","q":"Quelles sont les principales bactéries Cocci Gram positif fréquentes dans les infections de l'enfant et leurs caractéristiques morphologiques ?","a":"<ul><li><strong>Streptocoque</strong> : diplocoques en <strong>chaînettes</strong>.</li><li><strong>Pneumocoque</strong> : diplocoques <strong>lancéolés</strong>.</li><li><strong>Staphylocoque</strong> : diplocoques en <strong>amas</strong>.</li></ul>"},{"i":"6d4b6770423e","n":177,"o":"177-29","u":"Prise en charge","t":"Connaître les modalités de prescription d’une antibiothérapie chez le nourrisson et l’enfant","q":"Quelles sont les situations fréquentes en pédiatrie qui ne justifient typiquement PAS la prescription d'un antibiotique ?","a":"<ul><li><strong>Rhinopharyngite aiguë</strong>.</li><li><strong>OMA congestive</strong> ou <strong>séro-muqueuse</strong>.</li><li><strong>Angine aiguë</strong> à <strong>TDR négatif</strong> ou chez l'enfant de <strong>moins de 3 ans</strong>.</li><li><strong>Rhino-sinusite maxillaire</strong> en cas de signes bilatéraux diffus modérés, rhinorrhée séreuse, et fièvre modérée.</li><li><strong>Bronchiolite aiguë</strong> en l'absence de signe de surinfection bactérienne.</li><li><strong>Diarrhée aiguë liquidienne</strong> peu fébrile.</li></ul>"},{"i":"bc7ba882782c","n":177,"o":"177-29","u":"Prise en charge","t":"Connaître les modalités de prescription d’une antibiothérapie chez le nourrisson et l’enfant","q":"Dans quel contexte doit-on prescrire une antibiothérapie chez le nourrisson et l'enfant ?","a":"<p>Comme chez l'adulte, l'antibiothérapie ne doit être prescrite chez le nourrisson et l'enfant qu'en cas d'<strong>infection bactérienne avérée</strong>.</p>"},{"i":"d0ced3e3bb92","n":177,"o":"177-29","u":"Prise en charge","t":"Connaître les modalités de prescription d’une antibiothérapie chez le nourrisson et l’enfant","q":"Quelles sont les modalités importantes à considérer lors de la prescription d'une antibiothérapie chez le nourrisson et l'enfant ?","a":"<ul><li>Privilégier la <strong>voie orale</strong>.</li><li>Adapter la posologie au <strong>poids</strong> de l'enfant (en <strong>mg/kg</strong>).</li><li>Choisir une molécule à <strong>spectre adapté</strong> (l'<strong>amoxicilline</strong> couvre de nombreuses indications pédiatriques).</li><li>Tenir compte des <strong>contre-indications liées à l'âge</strong>, notamment les <strong>fluoroquinolones</strong> et les <strong>cyclines avant 8 ans</strong>.</li></ul>"},{"i":"506d7bc32bf8","n":177,"o":"177-3","u":"Définition","t":"Connaître les différentes classes d’antibiotiques","q":"Quel est le rôle de la rifampicine en dehors de son action sur les acides nucléiques, et comment doit-elle toujours être utilisée ?","a":"<p>La rifampicine est un <strong>antituberculeux majeur</strong>. Elle doit toujours être utilisée en <strong>association</strong> et jamais en monothérapie afin de prévenir l'émergence de résistances bactériennes.</p>"},{"i":"978bd29c443b","n":177,"o":"177-3","u":"Définition","t":"Connaître les différentes classes d’antibiotiques","q":"Quels antibiotiques ciblent les acides nucléiques bactériens ?","a":"<ul><li>Les <strong>fluoroquinolones</strong> (agissant sur l'ADN gyrase)</li><li>Les <strong>imidazolés</strong></li><li>La <strong>rifampicine</strong> (agissant sur l'ARN)</li></ul>"},{"i":"9b3ab5c30bb3","n":177,"o":"177-3","u":"Définition","t":"Connaître les différentes classes d’antibiotiques","q":"Quelles sont les classes d'antibiotiques agissant sur la synthèse protéique bactérienne, et sur quelle sous-unité du ribosome agissent-elles ?","a":"<ul><li>Sur la sous-unité <strong>30S</strong> : <strong>aminosides</strong> et <strong>cyclines</strong></li><li>Sur la sous-unité <strong>50S</strong> : <strong>macrolides</strong>, <strong>lincosamides</strong>, <strong>oxazolidinones</strong></li></ul>"},{"i":"c48f99fa432c","n":177,"o":"177-3","u":"Définition","t":"Connaître les différentes classes d’antibiotiques","q":"Quels sont les antibiotiques inhibant la synthèse des folates bactériens ?","a":"<p>Il s'agit des <strong>sulfamides</strong>, dont le <strong>cotrimoxazole</strong> (association sulfaméthoxazole-triméthoprime).</p>"},{"i":"c851a3ce9682","n":177,"o":"177-3","u":"Définition","t":"Connaître les différentes classes d’antibiotiques","q":"Selon quelle caractéristique principale les antibiotiques sont-ils classés ?","a":"<p>Les antibiotiques sont classés selon leur <strong>cible bactérienne spécifique</strong>.</p>"},{"i":"e026a9ebee38","n":177,"o":"177-3","u":"Définition","t":"Connaître les différentes classes d’antibiotiques","q":"Quelles sont les principales classes d'antibiotiques ciblant la paroi bactérienne ?","a":"<ul><li>Les <strong>β-lactamines</strong> (pénicillines, céphalosporines, monobactames, carbapénèmes)</li><li>Les <strong>glycopeptides</strong></li><li>La <strong>fosfomycine</strong></li></ul>"},{"i":"eb3248c85840","n":177,"o":"177-3","u":"Définition","t":"Connaître les différentes classes d’antibiotiques","q":"Quelles classes d'antibiotiques agissent sur la membrane bactérienne ?","a":"<ul><li>La <strong>daptomycine</strong></li><li>La <strong>colistine</strong> / <strong>polymyxines</strong></li></ul>"},{"i":"6d6b9997661d","n":177,"o":"177-31","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’enfant","q":"Quels sont les principes fondamentaux du bon usage des antibiotiques chez l'enfant, communs à l'adulte ?","a":"<p>Les principes fondamentaux du bon usage des antibiotiques chez l'enfant incluent :</p><ul><li>Réserver l'antibiotique aux <strong>infections bactériennes</strong> avérées.</li><li>Prescrire une <strong>durée courte</strong> de traitement.</li><li>Effectuer une <strong>réévaluation clinique</strong> régulière.</li><li>Privilégier la <strong>voie orale</strong> quand cela est possible.</li></ul>"},{"i":"71a23f56199b","n":177,"o":"177-31","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’enfant","q":"Quelles sont les pathologies courantes chez l'enfant pour lesquelles aucune éviction de la collectivité n'est nécessaire ?","a":"<p>Aucune éviction de la collectivité n'est nécessaire pour des pathologies telles que la <strong>bronchiolite</strong>, la <strong>rhinopharyngite</strong>, la <strong>grippe saisonnière</strong>, la <strong>varicelle</strong>, la <strong>méningite virale</strong> ou à pneumocoque, et les <strong>oreillons</strong>.</p>"},{"i":"887a7a682e5e","n":177,"o":"177-31","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’enfant","q":"Quel est le délai d'éviction de la collectivité recommandé pour la coqueluche chez l'enfant sous traitement antibiotique ?","a":"<p>Pour la coqueluche, l'éviction de la collectivité est recommandée pendant <strong>plus de 5 jours</strong> après le début de l'antibiothérapie. Ce délai peut être réduit à <strong>plus de 3 jours</strong> si le traitement est à base d'azithromycine.</p>"},{"i":"a288e8327300","n":177,"o":"177-31","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’enfant","q":"Quelle est la particularité épidémiologique des infections ORL et respiratoires chez l'enfant justifiant une prudence dans la prescription d'antibiotiques ?","a":"<p>La particularité épidémiologique chez l'enfant est que beaucoup d'infections ORL et respiratoires sont d'<strong>origine virale</strong>, rendant l'antibiothérapie inefficace et inappropriée.</p>"},{"i":"b223378ff885","n":177,"o":"177-31","u":"Prise en charge","t":"Comprendre le bon usage des antibiotiques chez l’enfant","q":"En pédiatrie, quels sont les délais d'éviction de la collectivité pour une angine streptococcique ou une scarlatine traitée par antibiotiques ?","a":"<p>En cas d'angine streptococcique ou de scarlatine, l'éviction de la collectivité est requise jusqu'à <strong>plus de 2 jours</strong> d'antibiothérapie.</p>"},{"i":"2dc494919edb","n":177,"o":"177-4","u":"Physiopathologie","t":"Connaître les principes du mode d’action d’un antibiotique","q":"Quel est le principe général du mode d'action des antibiotiques sur le cycle réplicatif bactérien ?","a":"<p>Les antibiotiques agissent principalement en interférant avec le <strong>cycle réplicatif des bactéries</strong>. Ils sont préférentiellement actifs sur les bactéries en <strong>phase de multiplication active</strong>. Les bactéries à croissance lente, comme dans les infections sur matériel ou les endocardites, sont moins sensibles à leur action.</p>"},{"i":"ccb328da069f","n":177,"o":"177-4","u":"Physiopathologie","t":"Connaître les principes du mode d’action d’un antibiotique","q":"Pourquoi les béta-lactamines sont-elles inactives sur les mycoplasmes et les glycopeptides inactifs sur les BGN ?","a":"<ul><li>Les béta-lactamines sont inactives sur les <strong>mycoplasmes</strong> car ces bactéries sont <strong>dépourvues de paroi</strong>, qui est pourtant la cible des béta-lactamines.</li><li>Les glycopeptides sont inactifs sur les <strong>BGN</strong> (Bacilles à Gram Négatif) car la <strong>membrane externe</strong> de ces bactéries ne laisse pas passer ces grosses molécules.</li></ul>"},{"i":"e27000912ba3","n":177,"o":"177-4","u":"Physiopathologie","t":"Connaître les principes du mode d’action d’un antibiotique","q":"Quelle est la particularité d'action des antibiotiques sur les bactéries intracellulaires ?","a":"<p>Seuls les antibiotiques <strong>pénétrant à l'intérieur de la cellule hôte</strong> sont actifs sur les bactéries intracellulaires. Exemples de ces antibiotiques : <strong>macrolides</strong>, <strong>fluoroquinolones</strong>, <strong>rifampicine</strong>, <strong>cyclines</strong>.</p>"},{"i":"f61a134c545d","n":177,"o":"177-4","u":"Physiopathologie","t":"Connaître les principes du mode d’action d’un antibiotique","q":"Comment les aminosides et les macrolides agissent-ils sur les bactéries ?","a":"<p>Les aminosides et les macrolides agissent en <strong>inhibant la synthèse protéique</strong> bactérienne, en se fixant sur le <strong>ribosome</strong> bactérien (sous-unité 30S pour les aminosides, 50S pour les macrolides).</p>"},{"i":"fa906d6e758b","n":177,"o":"177-4","u":"Physiopathologie","t":"Connaître les principes du mode d’action d’un antibiotique","q":"Quel est le mécanisme d'action des béta-lactamines sur les bactéries ?","a":"<p>Les béta-lactamines agissent en se liant aux <strong>PLP</strong> (Protèines de Liaison des Pénicillines), ce qui a pour conséquence de bloquer la <strong>synthèse du peptidoglycane</strong> de la paroi bactérienne et d'entraîner la lyse de la bactérie.</p>"}]};